import re,sys
txt=open('/tmp/tpl/df.txt').read().split('\n')
def docblock(o):
    pat=re.compile(r'^'+o+r'\s*=')
    i=[j for j,l in enumerate(txt) if pat.match(l)][0]
    j=i-1; block=[]
    while j>=0 and (txt[j].startswith('#') or txt[j].strip()==''):
        if txt[j].startswith('#'): block.append(txt[j])
        j-=1
    block.reverse()
    # stop at separator lines
    while block and re.match(r'^#-+$', block[0]): block.pop(0)
    return block
for o in sys.argv[1:]:
    print('### '+o)
    print('\n'.join(docblock(o)))
    print()
