{"command": "cd /workspace && cat > tools/genembed.cpp <<'EOF'
// Generates a C++ header with the template files embedded as byte arrays.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <dirent.h>
#include <sys/stat.h>

static std::string slurp(const std::string &path) {
    FILE *f = fopen(path.c_str(), "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path.c_str()); exit(1); }
    std::string out;
    char buf[65536];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), f)) > 0) out.append(buf, n);
    fclose(f);
    return out;
}

static void listFiles(const std::string &dir, const std::string &prefix,
                      std::vector<std::pair<std::string,std::string> > &out) {
    DIR *d = opendir(dir.c_str());
    if (!d) return;
    struct dirent *e;
    std::vector<std::string> names;
    while ((e = readdir(d)) != NULL) {
        std::string n = e->d_name;
        if (n == "." || n == "..") continue;
        names.push_back(n);
    }
    closedir(d);
    std::sort(names.begin(), names.end());
    for (size_t i = 0; i < names.size(); i++) {
        std::string full = dir + "/" + names[i];
        struct stat st;
        if (stat(full.c_str(), &st) != 0) continue;
        if (S_ISDIR(st.st_mode)) {
            listFiles(full, prefix + names[i] + "/", out);
        } else {
            out.push_back(std::make_pair(prefix + names[i], full));
        }
    }
}

static void emit(const std::string &varname, const std::string &data, FILE *o) {
    fprintf(o, "static const unsigned char %s[] = {\n", varname.c_str());
    for (size_t i = 0; i < data.size(); i++) {
        unsigned char c = (unsigned char)data[i];
        fprintf(o, "%d,%s", (int)c, ((i % 16) == 15) ? "\n" : " ");
    }
    if (data.size() % 16 != 0) fprintf(o, "\n");
    fprintf(o, "};\n");
}

int main(int argc, char **argv) {
    if (argc < 3) { fprintf(stderr, "usage: genembed <dir> <outfile>\n"); return 1; }
    std::vector<std::pair<std::string,std::string> > files;
    listFiles(argv[1], "", files);
    FILE *o = fopen(argv[2], "wb");
    if (!o) { fprintf(stderr, "cannot write %s\n", argv[2]); return 1; }
    fprintf(o, "// Auto-generated from templates/. Do not edit.\n");
    fprintf(o, "#ifndef GEN_EMBED_H\n#define GEN_EMBED_H\n");
    fprintf(o, "#include <cstddef>\n\n");
    for (size_t i = 0; i < files.size(); i++) {
        std::string var = "TPL_";
        std::string key = files[i].first;
        for (size_t j = 0; j < key.size(); j++) {
            char c = key[j];
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) var += c;
            else var += '_';
        }
        fprintf(o, "static const char tplName_%d[] = \"%s\";\n", (int)i, key.c_str());
    }
    fprintf(o, "\n");
    for (size_t i = 0; i < files.size(); i++) {
        std::string data = slurp(files[i].second);
        std::string var = "TPL_";
        std::string key = files[i].first;
        for (size_t j = 0; j < key.size(); j++) {
            char c = key[j];
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) var += c;
            else var += '_';
        }
        fprintf(o, "static const char tplFile_%d[] = \"%s\";\n", (int)i, key.c_str());
        emit(var, data, o);
    }
    fprintf(o, "\nstruct TplEntry { const char *name; const char *data; size_t len; };\n");
    fprintf(o, "static const TplEntry TEMPLATES[] = {\n");
    for (size_t i = 0; i < files.size(); i++) {
        std::string var = "TPL_";
        std::string key = files[i].first;
        for (size_t j = 0; j < key.size(); j++) {
            char c = key[j];
            if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')) var += c;
            else var += '_';
        }
        fprintf(o, "  { tplName_%d, (const char *)%s, sizeof(%s) },\n", (int)i, var.c_str(), var.c_str());
    }
    fprintf(o, "};\n");
    fprintf(o, "#endif\n");
    fclose(o);
    return 0;
}
EOF
