#include "util.h"
#include <sys/stat.h>
#include <sys/types.h>
#include <dirent.h>
#include <unistd.h>
#include <algorithm>
#include <fstream>
#include <sstream>
#include <functional>

std::string upperStr(const std::string &s){ std::string r=s; for(size_t i=0;i<r.size();i++) r[i]=toupper((unsigned char)r[i]); return r; }
std::string lowerStr(const std::string &s){ std::string r=s; for(size_t i=0;i<r.size();i++) r[i]=tolower((unsigned char)r[i]); return r; }
static bool isSpaceCh(char c){ return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\f'||c=='\v'; }
std::string stripWS(const std::string &s){ size_t b=0,e=s.size(); while(b<e&&isSpaceCh(s[b]))b++; while(e>b&&isSpaceCh(s[e-1]))e--; return s.substr(b,e-b); }
std::string stripLeadingWS(const std::string &s){ size_t b=0; while(b<s.size()&&isSpaceCh(s[b]))b++; return s.substr(b); }
std::string stripTrailingWS(const std::string &s){ size_t e=s.size(); while(e>0&&isSpaceCh(s[e-1]))e--; return s.substr(0,e); }
bool strStartsWith(const std::string &s,const std::string &p){ return s.size()>=p.size() && memcmp(s.data(),p.data(),p.size())==0; }
bool strEndsWith(const std::string &s,const std::string &p){ return s.size()>=p.size() && memcmp(s.data()+s.size()-p.size(),p.data(),p.size())==0; }
std::vector<std::string> splitStr(const std::string &s,const std::string &sep){
  std::vector<std::string> out; size_t p=0;
  if(sep.empty()){ out.push_back(s); return out; }
  while(p<=s.size()){ size_t q=s.find(sep,p); if(q==std::string::npos){ out.push_back(s.substr(p)); break;} out.push_back(s.substr(p,q-p)); p=q+sep.size(); }
  return out;
}
std::vector<std::string> tokenizeWS(const std::string &s){ std::vector<std::string> out; size_t i=0; while(i<s.size()){ while(i<s.size()&&isSpaceCh(s[i]))i++; size_t b=i; while(i<s.size()&&!isSpaceCh(s[i]))i++; if(i>b) out.push_back(s.substr(b,i-b)); } return out; }
std::string joinStr(const std::vector<std::string> &v,const std::string &sep){ std::string r; for(size_t i=0;i<v.size();i++){ if(i) r+=sep; r+=v[i]; } return r; }
std::string replaceAll(std::string s,const std::string &f,const std::string &r){ if(f.empty()) return s; std::string out; size_t p=0; while(p<s.size()){ size_t q=s.find(f,p); if(q==std::string::npos){ out+=s.substr(p); break;} out+=s.substr(p,q-p)+r; p=q+f.size(); } return out; }
std::string htmlEscape(const std::string &s){ std::string o; for(size_t i=0;i<s.size();i++){ unsigned char c=s[i]; switch(c){ case '<': o+="&lt;"; break; case '>': o+="&gt;"; break; case '&': o+="&amp;"; break; case '"': o+="&quot;"; break; case '\'': o+="&#39;"; break; default: o+=(char)c; } } return o; }
std::string latexEscape(const std::string &s){ std::string o; for(size_t i=0;i<s.size();i++){ unsigned char c=s[i]; switch(c){ case '$': o+="\\$"; break; case '&': o+="\\&"; break; case '%': o+="\\%"; break; case '#': o+="\\#"; break; case '_': o+="\\_"; break; case '{': o+="\\{"; break; case '}': o+="\\}"; break; default: o+=(char)c; } } return o; }
std::string numToString(long long v){ char b[64]; snprintf(b,sizeof(b),"%lld",v); return b; }
std::string numToString(int v){ return numToString((long long)v); }
std::string numToString(unsigned int v){ char b[64]; snprintf(b,sizeof(b),"%u",v); return b; }
long long stringToNum(const std::string &s){ return strtoll(s.c_str(),NULL,10); }
int strCompareIC(const std::string &a,const std::string &b){ size_t n=a.size()<b.size()?a.size():b.size(); for(size_t i=0;i<n;i++){ int x=tolower((unsigned char)a[i]),y=tolower((unsigned char)b[i]); if(x!=y) return x-y; } if(a.size()==b.size()) return 0; return a.size()<b.size()?-1:1; }
std::string subStr(const std::string &s,size_t st,size_t ln){ if(st>=s.size()) return ""; return s.substr(st,ln); }

bool fileExists(const std::string &p){ struct stat st; return stat(p.c_str(),&st)==0 && S_ISREG(st.st_mode); }
bool isDir(const std::string &p){ struct stat st; return stat(p.c_str(),&st)==0 && S_ISDIR(st.st_mode); }
bool makeDirs(const std::string &p){
  if(p.empty()) return true;
  if(isDir(p)) return true;
  std::string cur; std::vector<std::string> parts=splitStr(p,"/");
  for(size_t i=0;i<parts.size();i++){
    if(i) cur+="/"; cur+=parts[i];
    if(cur.empty()||cur=="/") continue;
    if(isDir(cur)) continue;
    if(mkdir(cur.c_str(),0755)!=0 && !isDir(cur)) return false;
  }
  return true;
}
std::string slurpFile(const std::string &path){
  std::ifstream f(path.c_str(), std::ios::binary);
  if(!f) return "";
  std::ostringstream ss; ss<<f.rdbuf(); return ss.str();
}
std::string dirNameOf(const std::string &p){ size_t q=p.find_last_of('/'); if(q==std::string::npos) return std::string("."); if(q==0) return "/"; return p.substr(0,q); }
std::string baseNameOf(const std::string &p){ size_t q=p.find_last_of('/'); if(q==std::string::npos) return p; return p.substr(q+1); }
std::string stripPath(const std::string &p){ return baseNameOf(p); }
std::string getcwdStr(){ char b[4096]; if(getcwd(b,sizeof(b))) return b; return std::string("."); }
bool isAbsolutePath(const std::string &p){ return !p.empty() && p[0]=='/'; }
std::string normalizePath(const std::string &p){
  std::vector<std::string> parts=splitStr(p,"/");
  std::vector<std::string> out;
  bool abs=strStartsWith(p,"/");
  for(size_t i=0;i<parts.size();i++){
    if(parts[i]=="."||parts[i]=="") continue;
    if(parts[i]==".."){ if(!out.empty()&&out.back()!="..") out.pop_back(); else if(!abs) out.push_back(".."); continue; }
    out.push_back(parts[i]);
  }
  std::string r=joinStr(out,"/");
  if(abs) r="/"+r;
  if(r.empty()) r=".";
  return r;
}

