static unsigned int rol(unsigned int x,int c){ return (x<<c)|(x>>(32-c)); }
static void transform(unsigned int h[4], const unsigned char block[64]){
  unsigned int w[16];
  for(int i=0;i<16;i++) w[i]=(unsigned int)block[i*4]|((unsigned int)block[i*4+1]<<8)|((unsigned int)block[i*4+2]<<16)|((unsigned int)block[i*4+3]<<24);
  unsigned int a=h[0],b=h[1],c=h[2],d=h[3];
  for(int i=0;i<64;i++){
    unsigned int f; int g;
    if(i<16){ f=(b&c)|((~b)&d); g=i; }
    else if(i<32){ f=(d&b)|((~d)&c); g=(5*i+1)%16; }
    else if(i<48){ f=b^c^d; g=(3*i+5)%16; }
    else { f=c^(b|(~d)); g=(7*i)%16; }
    unsigned int tmp=d; d=c; c=b;
    b=b+rol(a+f+K[i]+w[g],R[i]);
    a=tmp;
  }
  h[0]+=a; h[1]+=b; h[2]+=c; h[3]+=d;
}
}
std::string md5hex(const std::string &s){
  using namespace md5impl;
  unsigned int h[4]={0x67452301,0xefcdab89,0x98badcfe,0x10325476};
  std::string msg=s;
  msg.push_back((char)0x80);
  size_t pad=(56-(msg.size()%64))%64;
  msg.append(pad,'\0');
  unsigned long long blen=(unsigned long long)s.size()*8;
  for(int i=0;i<8;i++) msg.push_back((char)((blen>>(8*i))&0xff));
  for(size_t off=0;off+64<=msg.size();off+=64) transform(h,(const unsigned char*)msg.data()+off);
  char out[33];
  const char *hex="0123456789abcdef";
  for(int i=0;i<4;i++) for(int j=0;j<4;j++){ unsigned char by=(unsigned char)((h[i]>>(8*j))&0xff); out[i*4*2+j*2]=hex[by>>4]; out[i*4*2+j*2+1]=hex[by&15]; }
  out[32]=0;
  return out;
}
