cat > messages.cpp <<'EOF'
#include "messages.h"
#include "util.h"
#include <cstdio>
#include <cstdlib>
#include <unistd.h>

static std::string g_warnFormat = "$file:$line: $text";
static std::string g_warnLogfile;
static int g_warnAsError = 0;
static bool g_quiet = false;
static FILE *g_log = NULL;
int g_numWarnings = 0;

static std::string g_pending;

void setWarnFormat(const std::string &f){ g_warnFormat=f; }
void setWarnLineFormat(const std::string &f){ (void)f; }
void setWarnLogfile(const std::string &f){
  g_warnLogfile=f;
  if(g_log){ fclose(g_log); g_log=NULL; }
  if(f.empty()) return;
  if(f=="-") return;
  g_log=fopen(f.c_str(),"a");
}
void setWarnAsError(int m){ g_warnAsError=m; }
void setQuiet(bool q){ g_quiet=q; }

static void logWrite(const std::string &s){
  if(!g_log) return;
  fwrite(s.data(),1,s.size(),g_log);
  fflush(g_log);
}

void msgProgress(const std::string &s){
  if(g_quiet) return;
  g_pending += s;
  g_pending += "\n";
}
void msgFlush(){
  if(!g_pending.empty()){ fwrite(g_pending.data(),1,g_pending.size(),stdout); fflush(stdout); }
  g_pending.clear();
}

static std::string subst(const std::string &f,const std::string &file,int line,const std::string &text){
  std::string r=f;
  std::string l=numToString(line);
  size_t p=0;
  std::string out;
  while(p<r.size()){
    if(r[p]=='$'){
      if(strStartsWith(r.substr(p),"$file")){ out+=file; p+=5; continue; }
      if(strStartsWith(r.substr(p),"$line")){ out+=l; p+=5; continue; }
      if(strStartsWith(r.substr(p),"$text")){ out+=text; p+=5; continue; }
    }
    out+=r[p]; p++;
  }
  return out;
}

void warnPlain(const std::string &s){
  std::string m="warning: "+s+"\n";
  if(g_warnAsError>=1){ }
  if(!g_warnLogfile.empty() && g_warnLogfile=="-") { fprintf(stdout,"%s",m.c_str()); }
  fprintf(stderr,"%s",m.c_str());
  logWrite(m);
  g_numWarnings++;
  if(g_warnAsError==1){ msgFlush(); exit(1); }
}

void warnFormatted(const std::string &file,int line,const std::string &text){
  std::string f=g_warnFormat;
  if(f.empty()) f="$file:$line: $text";
  std::string m="warning: "+subst(f,file,line,text)+"\n";
  if(!g_warnLogfile.empty() && g_warnLogfile=="-") { fprintf(stdout,"%s",m.c_str()); }
  fprintf(stderr,"%s",m.c_str());
  logWrite(m);
  g_numWarnings++;
  if(g_warnAsError==1){ msgFlush(); exit(1); }
}

void errorExit(const std::string &s){
  msgFlush();
  fprintf(stderr,"error: %s\n",s.c_str());
  fflush(stderr);
  exit(1);
}
void configError(const std::string &s){ warnPlain(s); }
EOF
echo ok"}

