- `Config::order()` — return the vector of names in template order (built once).
- `parseText(text, fname)`.
- `validate()`.
- `writeTemplate(withComments)`.
- `writeDifference(withEnv)`.

For writeTemplate, I need the template text (df.txt or ds.txt). I'll access the embedded templates via a helper in assets.h.

Let me write assets.h first (template access).

Then config.cpp.

assets.h:
```cpp
std::string tplData(const std::string &name); // returns embedded file content
```

Let me write it.

Now config parse details. Let me define the parser over the raw text with an index and line counter.

```
void Config::parseText(const std::string &text, const std::string &fname)
```

Implementation:

```cpp
size_t i=0; int line=1;
std::string ident;
while(i<text.size()){
  char c=text[i];
  if(c==' '||c=='\t'){ i++; continue; }
  if(c=='\r'){ i++; continue; }
  if(c=='\n'){ line++; i++; continue; }
  if(c=='#'){ while(i<text.size() && text[i]!='\n') i++; continue; }
  if(c=='$' && i+1<text.size() && text[i+1]=='('){
     // env token: consume to matching ')'
     size_t j=i+2;
     while(j<text.size() && text[j]!=')' && text[j]!='\n') j++;
     if(j<text.size() && text[j]==')') i=j+1; else i++;
     continue;
  }
  if(c=='\\' && i+1<text.size() && (text[i+1]=='\n' || (text[i+1]=='\r' && i+2<text.size() && text[i+2]=='\n'))){
     i += (text[i+1]=='\r')?3:2; line++; continue;
  }
  if(isIdentStart(c)){
     // read ident
     size_t b=i;
     while(i<text.size() && isIdentChar(text[i])) i++;
     std::string id=text.substr(b,i-b);
     size_t save=i;
     while(i<text.size() && (text[i]==' '||text[i]=='\t')) i++;
     if(i<text.size() && text[i]=='='){
        i++; // consume
        std::string raw = readValue(text, i, line);
        applyOption(id, raw, line, fname, false);
     } else if(i+1<text.size() && text[i]=='+' && text[i+1]=='='){
        i+=2;
        std::string raw = readValue(text, i, line);
        applyOption(id, raw, line, fname, true);
     } else {
        i=save;
        warnPlain("ignoring unknown tag '"+id+"' at line "+numToString(line)+", file "+fname);
     }
     continue;
  }
  if(isdigit((unsigned char)c)){
     size_t b=i;
     while(i<text.size() && (isalnum((unsigned char)text[i])||text[i]=='_')) i++;
     std::string id=text.substr(b,i-b);
