void Config::parseText(const std::string &text, const std::string &fname){
  size_t i=0; int line=1;
  while(i<text.size()){
    char c=text[i];
    if(c==' '||c=='\t'){ i++; continue; }
    if(c=='\r'){ i++; continue; }
