static bool isBooleanValue(const std::string &s){
  return s=="YES"||s=="NO"||s=="yes"||s=="no"||s=="TRUE"||s=="FALSE"||s=="true"||s=="false"||s=="1"||s=="0";
}
static bool isNumericValue(const std::string &s){
  if(s.empty()) return false;
  size_t p=0;
  if(s[0]=='-'||s[0]=='+') p=1;
  if(p>=s.size()) return false;
  for(size_t i=p;i<s.size();i++) if(!isdigit((unsigned char)s[i])) return false;
  return true;
}
void Config::validate(){
  const std::vector<std::string> &ord=order();
  for(size_t k=0;k<ord.size();k++){
    const OptionData *d=meta(ord[k]);
    if(!d) continue;
    if(!has(ord[k])) continue;
    std::string v=str(ord[k]);
    if(v.empty()){
      if(d->type==T_STRING||d->type==T_LIST) continue;
      vals_[ord[k]].set=false;
      continue;
    }
    if(d->type==T_BOOL){
      if(!isBooleanValue(v)){
        warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid boolean value");
        warnPlain("Using the default: "+std::string(d->def)+"!");
        vals_[ord[k]].set=false;
      }
    } else if(d->type==T_NUMBER){
      if(!isNumericValue(v)){
        warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid number in the range ["+numToString(d->mn)+".."+numToString(d->mx)+"]!");
        warnPlain("Using the default: "+std::string(d->def)+"!");
        vals_[ord[k]].set=false;
      } else {
        long long n=stringToNum(v);
        if(n<d->mn||n>d->mx){
          warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid number in the range ["+numToString(d->mn)+".."+numToString(d->mx)+"]!");
          warnPlain("Using the default: "+std::string(d->def)+"!");
          vals_[ord[k]].set=false;
        }
      }
    } else if(d->type==T_ENUM){
      bool found=false;
      for(int i=0;i<48 && d->enumVals[i];i++) if(strCompareIC(d->enumVals[i],v)==0) found=true;
      if(!found){
        warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid enum value");
        warnPlain("Using the default: "+std::string(d->def)+"!");
        vals_[ord[k]].set=false;
      }
    }
  }
}

