}
void Config::appendList(const std::string &name,const std::vector<std::string> &v){
  OptValue &o=vals_[name]; o.set=true;
  for(size_t i=0;i<v.size();i++) o.items.push_back(v[i]);
}
void Config::clear(){ vals_.clear(); }

// ------------------------------------------------------------------ value helpers

std::string quoteOptionValue(const std::string &s){
  if(s.empty()) return std::string();
  bool need=false;
  for(size_t i=0;i<s.size();i++){ if(s[i]==' '||s[i]=='\t'||s[i]=='"') { need=true; break; } }
  if(!need) return s;
  std::string o="\"";
  for(size_t i=0;i<s.size();i++){ if(s[i]=='"') o+="\\"; o+=s[i]; }
  o+="\"";
  return o;
}

static std::string substituteEnvStr(const std::string &raw){
  std::string out;
  for(size_t i=0;i<raw.size();i++){
    if(raw[i]=='$' && i+1<raw.size() && raw[i+1]=='('){
      size_t j=i+2;
      while(j<raw.size() && raw[j]!=')') j++;
      if(j<raw.size()){
        std::string var=raw.substr(i+2,j-i-2);
        const char *v=getenv(var.c_str());
        out += (v?v:"");
        i=j;
        continue;
      }
    }
    out+=raw[i];
  }
  return out;
}

// Remove quotes: unescaped " removed, \" -> "
static std::string stripQuotes(const std::string &s){
  std::string out;
  for(size_t i=0;i<s.size();i++){
    if(s[i]=='\\' && i+1<s.size() && s[i+1]=='"'){ out+='"'; i++; continue; }
    if(s[i]=='"') continue;
    out+=s[i];
  }
  return out;
}

std::vector<std::string> parseOptionItems(const std::string &raw, OptType type){
  std::vector<std::string> out;
  if(type!=T_LIST) return out;
  std::string cur; bool inq=false;
  for(size_t i=0;i<raw.size();i++){
    char c=raw[i];
    if(c=='\\' && i+1<raw.size() && raw[i+1]=='"'){ cur+='"'; i++; continue; }
    if(c=='"'){
      if(inq){ inq=false; out.push_back(cur); cur.clear(); }
      else inq=true;
      continue;
    }
    if(!inq && (c==' '||c=='\t'||c==','||c=='\n'||c=='\r')){
      if(!cur.empty()){ out.push_back(cur); cur.clear(); }
      continue;
    }
    cur+=c;
  }
  if(!cur.empty()) out.push_back(cur);
  return out;
}

// ------------------------------------------------------------ config parsing

void Config::parseText(const std::string &text, const std::string &fname){
  size_t i=0; int line=1;
  while(i<text.size()){
    char c=text[i];
    if(c==' '||c=='\t'){ i++; continue; }
    if(c=='\r'){ i++; continue; }
    if(c=='\n'){ i++; line++; continue; }
    if(c=='#'){ while(i<text.size() && text[i]!='\n') i++; continue; }
    if(c=='$' && i+1<text.size() && text[i+1]=='('){
      size_t j=i+2;
      while(j<text.size() && text[j]!=')' && text[j]!='\n') j++;
      if(j<text.size() && text[j]==')') i=j+1; else i=j;
      continue;
    }
    if(c=='\\' && i+1<text.size() && text[i+1]=='\n'){ i+=2; line++; continue; }
    if((unsigned char)c>127 || isalnum((unsigned char)c) || c=='_'){
      size_t b=i;
      while(i<text.size() && (isalnum((unsigned char)text[i])||text[i]=='_')) i++;
      std::string id=text.substr(b,i-b);
      size_t save=i;
      while(i<text.size() && (text[i]==' '||text[i]=='\t')) i++;
      bool isAssign=false, isAppend=false;
      if(i<text.size() && text[i]=='='){ isAssign=true; i++; }
      else if(i+1<text.size() && text[i]=='+' && text[i+1]=='='){ isAppend=true; i+=2; }
      if(isAssign||isAppend){
        // read raw value
        std::string raw; bool inq=false;
        while(i<text.size()){
          char vc=text[i];
          if(vc=='\r'){ i++; continue; }
          if(vc=='\n'){ i++; line++; break; }
          if(vc=='\\' && i+1<text.size() && text[i+1]=='\n'){ raw+=' '; i+=2; line++; continue; }
          if(!inq && vc=='#') break;
          if(vc=='\\' && i+1<text.size() && text[i+1]=='"'){ raw+="\\\""; i+=2; continue; }
          if(vc=='"'){ inq=!inq; raw+='"'; i++; continue; }
          raw+=vc; i++;
        }
        std::string dispRaw=stripWS(raw);
        if(id=="INCLUDE"){
          std::string incval=stripQuotes(dispRaw);
          incval=stripWS(incval);
          if(!incval.empty()){
            std::string pth=incval;
            if(!isAbsolutePath(pth)){
              std::string bd=dirNameOf(fname);
              if(bd!="."&&bd!=""&&!strEndsWith(bd,"/")) pth=bd+"/"+incval;
              else pth=incval;
            }
            if(!fileExists(pth) && !isDir(pth)){
              errorExit("@INCLUDE = "+incval+": not found!");
              return;
            }
            std::string data=slurpFile(pth);
            parseText(data, pth);
          }
          continue;
        }
        const OptionData *d=meta(id);
        if(!d){
          warnPlain("ignoring unsupported tag '"+id+"' at line "+numToString(line)+", file "+fname);
        } else {
          // quote validation
          size_t openPos=0, closePos=0; int qcount=0; bool sepViolation=false;
          bool iq=false;
          for(size_t k=0;k<raw.size();k++){
            if(raw[k]=='\\' && k+1<raw.size() && raw[k+1]=='"'){ k++; continue; }
            if(raw[k]=='"'){
              if(iq){ iq=false; closePos=k; if(k+1<raw.size() && raw[k+1]!=' ' && raw[k+1]!='\t' && raw[k+1]!=',' && raw[k+1]!='\n' && raw[k+1]!='\r') sepViolation=true; }
              else { iq=true; openPos=k; }
              qcount++;
            }
          }
          bool quoteViolation = (qcount%2)!=0;
          if(sepViolation||quoteViolation){
            if(d->type==T_LIST){
              if(sepViolation) warnPlain("Invalid value for '"+id+"' tag at line "+numToString(line)+", file "+fname+": Values in list '"+dispRaw+"' are not properly space or comma separated");
              if(quoteViolation) warnPlain("Invalid value for '"+id+"' tag at line "+numToString(line)+", file "+fname+": Values in list '"+dispRaw+"' are not properly quoted");
            } else {
              if(sepViolation||quoteViolation) warnPlain("Invalid value for '"+id+"' tag at line "+numToString(line)+", file "+fname+": Value '"+dispRaw+"' is not properly quoted");
            }
          }
          std::string sub=substituteEnvStr(raw);
          std::vector<std::string> items=parseOptionItems(sub, d->type);
          if(d->type==T_LIST){
            if(isAppend) appendList(id, items); else setList(id, items);
          } else {
            std::string sval=stripWS(stripQuotes(sub));
            if(isAppend && has(id)){
              std::vector<std::string> cur=list(id);
              if(cur.empty()) cur.push_back("");
              cur[0]=cur[0]+" "+sval;
              setList(id,cur);
            } else setStr(id,sval);
          }
        }
        continue;
      }
      i=save;
      warnPlain("ignoring unknown tag '"+id+"' at line "+numToString(line)+", file "+fname);
      continue;
    }
    warnPlain("ignoring unknown character '"+std::string(1,c)+"' at line "+numToString(line)+", file "+fname);
    i++;
  }
}

// ------------------------------------------------------------ validation

static bool isBooleanValue(const std::string &s){
  return s=="YES"||s=="NO"||s=="yes"||s=="no"||s=="TRUE"||s=="FALSE"||s=="true"||s=="false"||s=="1"||s=="0";
}
static bool isNumericValue(const std::string &s){
  if(s.empty()) return false;
  size_t p=0;
  if(s[0]=='-'||s[0]=='+') p=1;
  if(p>=s.size()) return false;
  for(size_t i=p;i<s.size();i++) if(!isdigit((unsigned char)s[i])) return false;
  return true;
}
void Config::validate(){
  const std::vector<std::string> &ord=order();
  for(size_t k=0;k<ord.size();k++){
    const OptionData *d=meta(ord[k]);
    if(!d) continue;
    if(!has(ord[k])) continue;
    std::string v=str(ord[k]);
    if(v.empty()){
      if(d->type==T_STRING||d->type==T_LIST) continue;
      vals_[ord[k]].set=false;
      continue;
    }
    if(d->type==T_BOOL){
      if(!isBooleanValue(v)){
        warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid boolean value");
        warnPlain("Using the default: "+std::string(d->def)+"!");
        vals_[ord[k]].set=false;
      }
    } else if(d->type==T_NUMBER){
      if(!isNumericValue(v)){
        warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid number in the range ["+numToString(d->mn)+".."+numToString(d->mx)+"]!");
        warnPlain("Using the default: "+std::string(d->def)+"!");
        vals_[ord[k]].set=false;
      } else {
        long long n=stringToNum(v);
        if(n<d->mn||n>d->mx){
          warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid number in the range ["+numToString(d->mn)+".."+numToString(d->mx)+"]!");
          warnPlain("Using the default: "+std::string(d->def)+"!");
          vals_[ord[k]].set=false;
        }
      }
    } else if(d->type==T_ENUM){
      bool found=false;
      for(int i=0;i<48 && d->enumVals[i];i++) if(strCompareIC(d->enumVals[i],v)==0) found=true;
      if(!found){
        warnPlain("argument '"+v+"' for option "+ord[k]+" is not a valid enum value");
        warnPlain("Using the default: "+std::string(d->def)+"!");
        vals_[ord[k]].set=false;
      }
    }
  }
}

// ------------------------------------------------------------ output

std::string formatOptionValue(const OptionData *d, const std::vector<std::string> &items){
  std::string out;
  if(d->type==T_LIST){
    if(items.empty()) return out;
    for(size_t i=0;i<items.size();i++){
      out+=quoteOptionValue(items[i]);
      if(i+1<items.size()) out+=" \\\n                         ";
    }
    return out;
  }
  if(items.empty()) return out;
  return quoteOptionValue(items[0]);
}

static void writeTemplateFrom(const std::string &tpl, const Config &cfg, std::string &out){
  std::vector<std::string> lines=splitStr(tpl,"\n");
  // remove trailing empty line handling: we keep everything
  for(size_t i=0;i<lines.size();i++){
    std::string l=lines[i];
    // does this line start an option?
    size_t p=0;
    while(p<l.size() && (l[p]==' '||l[p]=='\t')) p++;
    bool opt=false;
    if(p<l.size()){
      size_t b=p;
      while(p<l.size() && (isalnum((unsigned char)l[p])||l[p]=='_')) p++;
      while(p<l.size() && (l[p]==' '||l[p]=='\t')) p++;
      if(p<l.size() && l[p]=='=' && p>b) opt=true;
    }
    if(opt){
      // gather continuation lines
      size_t j=i+1;
      while(j<lines.size() && strEndsWith(lines[j],"\\")) j++;
      std::string id=l.substr(0,l.find_first_of(" \t="));
      std::string val;
      const OptionData *d=Config::meta(id);
      if(d){
        if(cfg.has(id)) val=formatOptionValue(d,cfg.list(id));
        else {
          // default from template: reconstruct
          std::string raw=l.substr(l.find('=')+1);
          for(size_t k=i+1;k<j;k++){ raw=raw.substr(0,raw.size()-1)+" "+lines[k]; }
          size_t h=raw.find('#'); if(h!=std::string::npos) raw=raw.substr(0,h);
          val=formatOptionValue(d,parseOptionItems(substituteEnvStr(raw),d->type));
          if(d->type!=T_LIST) val=quoteOptionValue(stripWS(stripQuotes(raw)));
        }
      }
      out+=id;
      for(size_t k=id.size();k<23;k++) out+=' ';
      out+="= ";
      out+=val;
      out+="\n";
      i=j-1;
      continue;
    }
    out+=l;
    out+="\n";
  }
}

std::string Config::writeTemplate(bool withComments) const {
  std::string tpl=tplData(withComments?"df.txt":"ds.txt");
  std::string out;
  writeTemplateFrom(tpl,*this,out);
  return out;
}

std::string Config::writeDifference(bool withEnv) const {
  std::string out="# Difference with default Doxyfile "+std::string(DOXY_VERSION)+" ("+std::string(DOXY_HASH)+")\n";
  const std::vector<std::string> &ord=order();
  for(size_t k=0;k<ord.size();k++){
    const OptionData *d=meta(ord[k]);
    if(!d) continue;
    std::string cur;
    if(has(ord[k])) cur=formatOptionValue(d,list(ord[k]));
    else {
      std::string dv=d->def;
      if(d->type==T_LIST) cur=formatOptionValue(d,parseOptionItems(dv,T_LIST));
      else cur=quoteOptionValue(stripWS(stripQuotes(dv)));
    }
    std::string dv;
    if(d->type==T_LIST) dv=formatOptionValue(d,parseOptionItems(d->def,T_LIST));
    else dv=quoteOptionValue(stripWS(stripQuotes(d->def)));
    if(cur!=dv){
      out+=ord[k];
      for(size_t i=ord[k].size();i<23;i++) out+=' ';
      out+="= ";
      out+=cur;
      out+="\n";
    }
  }
  return out;
}
