int main(int argc, char **argv){
  bool shortMode=false;
  bool generateCfg=false;
  bool updateCfg=false;
  bool dumpSymbolMap=false;
  std::string compareFile;
  bool compareMode=false, compareNoEnv=false;
  std::string commentFile;
  bool haveComment=false;
  std::string configName;
  bool haveConfig=false;

  int i=1;
  for(;i<argc;i++){
    std::string a=argv[i];
    if(a=="-h"||a=="-?"){ printUsage(argv[0]); return 0; }
    else if(a=="-d"){
      if(i+1>=argc){ printDevParams(); return 0; }
      std::string lvl=argv[++i];
      bool ok=false;
      for(int k=0;DEBUG_LEVELS[k];k++) if(lvl==DEBUG_LEVELS[k]) ok=true;
      if(!ok){
        msgStdout("option \"-d\" has unknown debug specifier: \""+lvl+"\".\n");
        printDevParams();
        return 1;
      }
      g_debug.insert(lvl);
    }
    else if(a=="-s"){ shortMode=true; }
    else if(a=="-b"){ }
    else if(a=="-q"){ setQuiet(true); }
    else if(a=="-v"){ printf("%s\n",DOXY_VERSION_FULL); fflush(stdout); return 0; }
    else if(a=="-V"){ printf("%s\n",DOXY_VERSION_FULL); printf("    with sqlite3 3.42.0.\n"); fflush(stdout); return 0; }
    else if(a=="-m"){ dumpSymbolMap=true; }
    else if(a=="-c"){
      if(i+1>=argc){
        msgStdout("option \"-c\" is missing the file name to read\n");
        printDevParams();
        return 1;
      }
      commentFile=argv[++i]; haveComment=true;
    }
    else if(a=="-u"){ updateCfg=true; }
    else if(a=="-g"){ generateCfg=true; }
    else if(a=="-l"){
      std::string name="DoxygenLayout.xml";
      if(i+1<argc) name=argv[++i];
      std::string data=tplData("layout.xml");
      if(!writeFile(name,data,true)){
        errorExit("Cannot open file "+name+" for writing");
        return 1;
      }
      return 0;
    }
    else if(a=="-e"){
      if(i+1>=argc){ errorExit("option \"-e\" is missing format specifier rtf."); return 1; }
      std::string fmt=argv[++i];
      if(fmt!="rtf"){ errorExit("option \"-e\" has invalid format specifier."); return 1; }
      if(i+1>=argc){ errorExit("option \"-e rtf\" is missing an extensions file name"); return 1; }
      std::string name=argv[++i];
      std::string data=tplData("rtf_ext.txt");
      if(!writeFile(name,data,true)){
        errorExit("Cannot open file "+name+" for writing");
        return 1;
      }
      return 0;
    }
    else if(a=="-f"){
      if(i+1>=argc){ errorExit("option \"-f\" is missing list specifier."); return 1; }
      std::string fmt=argv[++i];
      if(fmt!="emoji"){ errorExit("option \"-f\" has invalid list specifier."); return 1; }
      if(i+1>=argc){ errorExit("option \"-f emoji\" is missing an output file name"); return 1; }
      std::string name=argv[++i];
      std::string data=tplData("emoji.txt");
      if(!writeFile(name,data,true)){
        errorExit("Cannot open file "+name+" for writing");
        return 1;
      }
      return 0;
    }
    else if(a=="-w"){
      if(i+1>=argc){ errorExit("option \"-w\" is missing format specifier rtf, html or latex"); return 1; }
      std::string fmt=argv[++i];
      if(fmt=="rtf"){
        if(i+1>=argc){ errorExit("option \"-w rtf\" is missing a style sheet file name"); return 1; }
        std::string name=argv[++i];
        std::string data=tplData("rtf_style.txt");
        if(!writeFile(name,data,true)){ errorExit("Cannot open file "+name+" for writing"); return 1; }
        return 0;
      } else if(fmt=="html"||fmt=="latex"){
        if(i+2>=argc){ errorExit("option \"-w "+fmt+"\" does not have enough arguments"); return 1; }
        std::string h=argv[++i], f=argv[++i], s=argv[++i];
        std::string cfgName;
        if(i+1<argc){
          cfgName=argv[i+1];
          if(cfgName!="-" && !fileExists(cfgName) && !isDir(cfgName)){
            errorExit("file '"+cfgName+"' not found or could not be opened\nExiting...");
            return 1;
          }
        }
        std::string hdr=tplData(fmt=="html"?"html_header.html":"latex_header.tex");
        std::string ftr=tplData(fmt=="html"?"html_footer.html":"latex_footer.tex");
        std::string sty=tplData(fmt=="html"?"doxygen.css":"latex_style.sty");
        if(!cfgName.empty()){
          Config c;
          std::string data = (cfgName=="-")?readAllStdin():slurpFile(cfgName);
          c.parseText(data,cfgName);
          c.validate();
          setWarnFormat(c.str("WARN_FORMAT"));
        }
        if(!writeFile(h,hdr,true)){ errorExit("Cannot open file "+h+" for writing"); return 1; }
        if(!writeFile(f,ftr,true)){ errorExit("Cannot open file "+f+" for writing"); return 1; }
        if(!writeFile(s,sty,true)){ errorExit("Cannot open file "+s+" for writing"); return 1; }
        return 0;
      } else {
        errorExit("Illegal format specifier \""+fmt+"\": should be one of rtf, html or latex");
        return 1;
      }
    }
    else if(a=="-x"||a=="-x_noenv"){
      compareMode=true; compareNoEnv=(a=="-x_noenv");
      if(i+1<argc){ compareFile=argv[i+1]; i++; }
      continue;
    }
    else if(a.size()>0 && a[0]=='-'){
      printUsage(argv[0]);
      fprintf(stderr,"error: Unknown option \"%s\"\n",a.c_str());
      fflush(stderr);
      return 1;
    }
    else {
      configName=a; haveConfig=true;
    }
  }

  // ----- configuration compare mode
  if(compareMode){
    Config cfg;
    if(compareFile=="-"){
      std::string data=readAllStdin();
      cfg.parseText(data,"-");
    } else {
      if(compareFile.empty()) compareFile="Doxyfile";
      if(!fileExists(compareFile) && !isDir(compareFile)){
        printUsage(argv[0]);
        fprintf(stderr,"error: configuration file %s not found!\n",compareFile.c_str());
        fflush(stderr);
        return 1;
      }
      std::string data=slurpFile(compareFile);
      cfg.parseText(data,compareFile);
    }
    cfg.validate();
    if(cfg.str("WARN_FORMAT").find("$file")==std::string::npos) warnPlain("warning format does not contain a $file tag!");
    if(cfg.str("WARN_FORMAT").find("$line")==std::string::npos) warnPlain("warning format does not contain a $line tag!");
    if(cfg.str("WARN_FORMAT").find("$text")==std::string::npos) warnPlain("warning format does not contain a $text tag!");
    msgStdout(cfg.writeDifference(!compareNoEnv));
    return 0;
  }

