      fprintf(stderr,"error: Doxyfile not found and no input file specified!\n");
      fflush(stderr);
      return 1;
    }
    cfg.parseText(slurpFile("Doxyfile"),"Doxyfile");
  }
  cfg.validate();

  // WARN_FORMAT checks
  {
    std::string wf=cfg.str("WARN_FORMAT");
    if(wf.empty()) wf="$file:$line: $text";
    if(wf.find("$file")==std::string::npos) warnPlain("warning format does not contain a $file tag!");
    if(wf.find("$line")==std::string::npos) warnPlain("warning format does not contain a $line tag!");
    if(wf.find("$text")==std::string::npos) warnPlain("warning format does not contain a $text tag!");
    setWarnFormat(wf);
    setWarnLogfile(cfg.str("WARN_LOGFILE"));
    int wae=0;
    std::string v=cfg.enumVal("WARN_AS_ERROR");
    if(v=="YES") wae=1;
    else if(v=="FAIL_ON_WARNINGS") wae=2;
    else if(v=="FAIL_ON_WARNINGS_PRINT") wae=3;
    setWarnAsError(wae);
    setQuiet(cfg.boolVal("QUIET"));
  }

  if(haveComment){ return runCommentConvert(cfg, commentFile); }
  return runDoxygen(cfg, dumpSymbolMap, commentFile);
}
