{"command": "cd /workspace && python3 - <<'PY'
p='src/config.cpp'
s=open(p).read()
start=s.index('static void writeTemplateFrom(')
end=s.index('std::string Config::writeDifference(')
new = r'''static void writeTemplateFrom(const std::string &tpl, const Config &cfg, std::string &out){
  std::vector<std::string> lines=splitStr(tpl,"\n");
  size_t n=lines.size();
  for(size_t i=0;i<n;i++){
    std::string l=lines[i];
    size_t p=0;
    while(p<l.size() && (l[p]==' '||l[p]=='\t')) p++;
    bool opt=false;
    size_t b=p;
    while(p<l.size() && (isalnum((unsigned char)l[p])||l[p]=='_')) p++;
    size_t idEnd=p;
    while(p<l.size() && (l[p]==' '||l[p]=='\t')) p++;
    if(p<l.size() && l[p]=='=' && p>b) opt=true;
    if(opt){
      size_t j=i;
      while(j+1<n && strEndsWith(lines[j],"\\")) j++;
      std::string id=l.substr(0,idEnd);
      std::string val;
      const OptionData *d=Config::meta(id);
      if(d){
        if(cfg.has(id)){
          val=formatOptionValue(d,cfg.list(id));
        } else {
          std::string raw=l.substr(p+1);
          for(size_t k=i+1;k<=j;k++){ raw=raw.substr(0,raw.size()-1)+" "+lines[k]; }
          size_t h=raw.find('#');
          if(h!=std::string::npos) raw=raw.substr(0,h);
          std::string sub=substituteEnvStr(raw);
          if(d->type==T_LIST){
            val=formatOptionValue(d,parseOptionItems(sub,T_LIST));
          } else {
            val=quoteOptionValue(stripWS(stripQuotes(sub)));
          }
        }
      }
      out+=id;
      for(size_t k=id.size();k<23;k++) out+=' ';
      out+='=';
      if(!val.empty()) out+=' '+val;
      out+='\n';
      i=j;
      continue;
    }
    out+=l;
    out+='\n';
  }
}

'''
s=s[:start]+new+s[end:]
s=s.replace('std::string tpl=tplData(withComments?"df.txt":"ds.txt");','std::string tpl=tplData(withComments?"ds.txt":"df.txt");')
open(p,'w').write(s)
PY
./compile.sh 2>&1|head -5; cd /tmp && rm -rf g1 && mkdir g1 && cd g1 && /workspace/executable -g full.cfg >/dev/null 2>&1 && diff full.cfg /tmp/tpl/df.txt && echo "FULL SAME"; /workspace/executable -s -g short.cfg >/dev/null 2>&1 && diff short.cfg /tmp/tpl/ds.txt && echo "SHORT SAME""}

