const Tok &FileParser::peek(size_t off) const {
  static Tok dummy={4,"",0};
  if(pos+off>=toks.size()) return dummy;
  return toks[pos+off];
}
const Tok &FileParser::next(){
  static Tok dummy={4,"",0};
  if(pos>=toks.size()) return dummy;
  return toks[pos++];
}
bool FileParser::is(const char *s, size_t off) const {
  if(pos+off>=toks.size()) return false;
  return toks[pos+off].text==s;
}

void FileParser::skipToSemiOrBrace(std::vector<Tok> &sig, int &stop){
  int depth=0;  // paren/bracket depth inside signature
  while(!atEnd()){
    const Tok &t=peek();
    if(t.type==4){
      if(t.text=="("||t.text=="["||t.text=="<") depth++;
      else if(t.text==")"||t.text=="]"){ if(depth==0){ stop=1; return; } depth--; }
      else if(t.text==">"){ if(depth==0){ stop=0; return; } depth--; }
      else if(t.text=="{"){ if(depth==0){ stop=2; return; } }
      else if(t.text=="}"){ if(depth==0){ stop=3; return; } }
      else if(t.text==";"){ if(depth==0){ stop=1; return; } }
    }
    sig.push_back(next());
  }
  stop=0;
}
