// ---------------------------------------------------------------- file collection
static bool matchPattern(const std::string &name, const std::string &pat){
  // simple wildcard match supporting * and ?
  size_t np=0, pp=0, star=std::string::npos, mark=0;
  while(np<name.size()){
    if(pp<pat.size() && (pat[pp]=='?' || pat[pp]==name[pp])) { np++; pp++; }
    else if(pp<pat.size() && pat[pp]=='*'){ star=pp; mark=np; pp++; }
    else if(star!=std::string::npos){ pp=star+1; np=++mark; }
    else return false;
  }
  while(pp<pat.size() && pat[pp]=='*') pp++;
  return pp==pat.size();
}

bool isSourceFile(const std::string &name, const Config &cfg){
