static void collectDir(const std::string &dir, bool recursive, const Config &cfg,
                       const std::vector<std::string> &exclude, const std::vector<std::string> &exclPat,
                       std::vector<std::string> &out){
  DIR *d=opendir(dir.c_str());
  if(!d) return;
  struct dirent *e;
  std::vector<std::string> names;
  while((e=readdir(d))!=NULL){
    std::string n=e->d_name;
    if(n=="."||n=="..") continue;
    names.push_back(n);
  }
  closedir(d);
  std::sort(names.begin(),names.end(), [](const std::string&a,const std::string&b){ return strCompareIC(a,b)<0; });
  for(size_t i=0;i<names.size();i++){
    std::string full=dir+"/"+names[i];
    if(dir=="/") full="/"+names[i];
    struct stat st;
    if(stat(full.c_str(),&st)!=0) continue;
    bool ex=false;
    for(size_t k=0;k<exclude.size();k++){
      std::string e2=exclude[k];
      if(!e2.empty() && e2[0]=='/') { if(full==e2 || (strStartsWith(full,e2) && (e2.size()==full.size()||e2[e2.size()-1]=='/'))) ex=true; }
      else {
        std::string ap=dir+"/"+e2;
        if(full==ap) ex=true;
        if(names[i]==e2) ex=true;
      }
    }
    for(size_t k=0;k<exclPat.size();k++) if(matchPattern(names[i],exclPat[k])) ex=true;
    if(ex) continue;
    if(S_ISDIR(st.st_mode)){
      if(recursive) collectDir(full,recursive,cfg,exclude,exclPat,out);
    } else if(S_ISREG(st.st_mode)){
      if(isSourceFile(names[i],cfg)) out.push_back(full);
    }
  }
}

std::vector<std::string> collectInputFiles(const Config &cfg){
  std::vector<std::string> out;
  std::vector<std::string> inputs=cfg.list("INPUT");
  std::vector<std::string> ex=cfg.list("EXCLUDE");
  std::vector<std::string> ep=cfg.list("EXCLUDE_PATTERNS");
  bool rec=cfg.boolVal("RECURSIVE");
  for(size_t i=0;i<inputs.size();i++){
