static bool isIdentCh(char c){ return isalnum((unsigned char)c)||c=='_'||c=='$'||(unsigned char)c>=128; }

void FileParser::tokenize(const std::string &src){
  size_t i=0; int ln=1;
  toks.clear();
  while(i<src.size()){
    char c=src[i];
    if(c=='\n'){ ln++; i++; continue; }
    if(c==' '||c=='\t'||c=='\r'){ i++; continue; }
    if(c=='/' && i+1<src.size()){
      if(src[i+1]=='/'){
        size_t j=i;
        while(j<src.size() && src[j]!='\n') j++;
        std::string t=src.substr(i,j-i);
        DocComment dc; dc.startLine=ln; dc.endLine=ln; dc.text=t; dc.briefStyle=false; dc.isSpecial=false;
        comments.push_back(dc);
        i=j; continue;
      }
      if(src[i+1]=='*'){
        size_t j=i+2;
        bool isSpecial=false;
        if(j<src.size() && src[j]=='<'){ isSpecial=true; j++; }
        size_t start=j;
        int eln=ln;
        while(j+1<src.size() && !(src[j]=='*' && src[j+1]=='/')){ if(src[j]=='\n') eln++; j++; }
        size_t end=j;
        if(j+1<src.size()){ j+=2; }
        std::string t=src.substr(start,end-start);
        DocComment dc; dc.startLine=ln; dc.endLine=eln; dc.text=t; dc.briefStyle=false; dc.isSpecial=isSpecial;
        comments.push_back(dc);
        i=j; continue;
      }
    }
    if(isdigit((unsigned char)c) || (c=='.' && i+1<src.size() && isdigit((unsigned char)src[i+1]))){
      size_t j=i;
      while(j<src.size() && (isalnum((unsigned char)src[j])||src[j]=='.'||src[j]=='_')) j++;
      if(j<src.size() && (src[j]=='+'||src[j]=='-') && j>i && (src[j-1]=='e'||src[j-1]=='E')){ j++; while(j<src.size() && isdigit((unsigned char)src[j])) j++; }
      toks.push_back({1,src.substr(i,j-i),ln}); i=j; continue;
    }
    if(c=='"' || c=='\''){
      char q=c; size_t j=i+1;
      while(j<src.size()){
        if(src[j]=='\\'){ j+=2; continue; }
        if(src[j]==q){ j++; break; }
        if(src[j]=='\n'){ ln++; j++; continue; }
        j++;
      }
      toks.push_back({q=='"'?2:3,src.substr(i,j-i),ln}); i=j; continue;
    }
    if(c=='#'){
      size_t j=i;
      while(j<src.size() && src[j]!='\n'){ j++; }
      // handle continuation
      while(j>0 && src[j-1]=='\\' && j<src.size()){
        j++;
        while(j<src.size() && src[j]!='\n') j++;
      }
      toks.push_back({5,src.substr(i,j-i),ln}); ln++; i=j+1; if(i<src.size()) { } continue;
    }
    // multi char operators
    static const char *mops[]={"::","->","<<",">>","<=",">=","==","!=","&&","||","++","--","+=","-=","*=","/=","%=","&=","|=","^=","<<=",">>=","->*","...",NULL};
    bool matched=false;
    for(int k=0;mops[k];k++){
      size_t l=strlen(mops[k]);
      if(src.compare(i,l,mops[k])==0){ toks.push_back({4,mops[k],ln}); i+=l; matched=true; break; }
    }
    if(matched) continue;
    if(isIdentCh(c)){
      size_t j=i;
      while(j<src.size() && isIdentCh(src[j])) j++;
      toks.push_back({0,src.substr(i,j-i),ln}); i=j; continue;
    }
    toks.push_back({4,std::string(1,c),ln}); i++;
  }
}

