// strip a doxygen comment to its raw content
static std::string stripComment(const std::string &raw, bool lineComment){
  if(lineComment){
    std::string t=raw;
    // "///", "//!", "///<", "//!"
    if(strStartsWith(t,"///")) t=t.substr(3);
    else if(strStartsWith(t,"//!")) t=t.substr(3);
    else t=t.substr(2);
    return t;
  }
  std::string t=raw;
  if(strStartsWith(t,"/**")) t=t.substr(3);
  else if(strStartsWith(t,"/*!")) t=t.substr(3);
  else if(strStartsWith(t,"/*")) t=t.substr(2);
  if(strEndsWith(t,"*/")) t=t.substr(0,t.size()-2);
  return t;
}

std::string FileParser::docFor(int declLine, int *commentLine, bool *found){
  // find the most recent unused comment that ends before declLine and is adjacent
  // prefer special (trailing) comments on the same line
  for(size_t i=curComment;i<comments.size();i++){
