// ---------------------------------------------------------------- declaration parsing

static std::string sigText(const std::vector<Tok> &v, size_t from=0, size_t to=std::string::npos){
  std::string s;
  size_t end = (to==std::string::npos)?v.size():to;
  for(size_t i=from;i<end;i++){ if(i>from) s+=" "; s+=v[i].text; }
  return s;
}
static bool isQual(const std::string &s){
  static const char *q[]={"static","inline","virtual","explicit","friend","constexpr","extern","mutable",
    "__inline__","__inline","__attribute__","__declspec","register","auto","thread_local","_Noreturn",
    "Q_DECL_EXPORT","Q_DECL_IMPORT",NULL};
  for(int i=0;q[i];i++) if(s==q[i]) return true;
  return false;
}
static bool isTypeKw(const std::string &s){
  static const char *q[]={"class","struct","union","enum","namespace","interface","exception","template","typedef","using","public","private","protected","operator",NULL};
  for(int i=0;q[i];i++) if(s==q[i]) return true;
  return false;
}

// Find index of the top-level '(' in sig (paren depth 0)
static int findParen(const std::vector<Tok> &sig){
  int depth=0;
  for(size_t i=0;i<sig.size();i++){
    if(sig[i].type!=4) continue;
    const std::string &t=sig[i].text;
    if(t=="(") { if(depth==0) return (int)i; depth++; }
    else if(t==")") depth--;
    else if(t=="<"||t=="[") depth++;
    else if(t==">"||t=="]") depth--;
  }
  return -1;
}
static int matchingParen(const std::vector<Tok> &sig, int start){
  int depth=0;
  for(size_t i=start;i<sig.size();i++){
    if(sig[i].type!=4) continue;
    if(sig[i].text=="(") depth++;
    else if(sig[i].text==")"){ depth--; if(depth==0) return (int)i; }
  }
  return -1;
}

void FileParser::parseBody(ClassDef *owner, const std::string &prot, int depth){
  // parse declarations inside a class/namespace body until the matching closing brace
  std::string curProt=prot;
  while(!atEnd()){
    const Tok &t=peek();
    if(t.type==4 && t.text=="}"){ next(); return; }
    if(t.type==4 && (t.text=="public"||t.text=="private"||t.text=="protected") && is(":",1)){
      curProt=t.text; next(); next(); continue;
    }
    if(t.type==4 && t.text==";"){ next(); continue; }
    if(t.type==0 && (t.text=="Q_OBJECT"||t.text=="Q_GADGET") && is(";",1)){ next(); next(); continue; }
    if(t.type==4 && t.text=="Q_SIGNALS" && is(":",1)){ curProt="signals"; next(); next(); continue; }
    if(t.type==4 && t.text=="Q_SLOTS" && is(":",1)){ curProt="slots"; next(); next(); continue; }
    if(t.type==0 && t.text=="signals" && is(":",1)){ curProt="signals"; next(); next(); continue; }
    if(t.type==0 && t.text=="slots" && is(":",1)){ curProt="slots"; next(); next(); continue; }
    if(t.type==4 && t.text==";"){ next(); continue; }
    if(t.type==5){ next(); continue; }   // preprocessor
    if(t.type==4 && t.text==";"){ next(); continue; }
    parseDeclaration(NULL, curProt, owner);
  }
}

void FileParser::parseDeclaration(void *unused, const std::string &prot, ClassDef *owner){
  (void)unused;
  int docLine=0; bool found=false;
  std::string doc=docFor(peek().line,&docLine,&found);
  std::vector<Tok> sig;
  int stop=0;
  size_t startPos=pos;
  skipToSemiOrBrace(sig,stop);
  if(sig.empty()){
    if(!atEnd() && (peek().text==";"||peek().text=="}"||peek().text=="{"||peek().text==")")) next();
    return;
  }
  // skip access/label tokens
  size_t i=0;
  // template prefix
  if(!sig.empty() && sig[0].text=="template"){
    i=1;
    if(i<sig.size() && sig[i].text=="<"){
      int d=0;
      while(i<sig.size()){
        if(sig[i].text=="<") d++;
        else if(sig[i].text==">"){ d--; if(d==0){ i++; break; } }
        i++;
      }
    }
  }
  // find keyword
  std::string kw;
  size_t kwIdx=std::string::npos;
  for(size_t k=i;k<sig.size();k++){
    if(sig[k].type==0 && isTypeKw(sig[k].text) && sig[k].text!="operator"){ kw=sig[k].text; kwIdx=k; break; }
    if(sig[k].text=="~"){ kw="dtor"; kwIdx=k; break; }
  }
  if(kwIdx!=std::string::npos && kw=="typedef"){
    parseVar(sig,doc,docLine,owner,prot,stop>=2,"");
    return;
  }
  if(kwIdx!=std::string::npos && kw=="using"){
    parseVar(sig,doc,docLine,owner,prot,stop>=2,"");
    return;
  }
  if(kwIdx!=std::string::npos && (kw=="class"||kw=="struct"||kw=="union"||kw=="interface"||kw=="exception")){
    parseClass(sig,doc,docLine);
    return;
  }
  if(kwIdx!=std::string::npos && (kw=="enum")){
    parseEnum(sig,doc,docLine,owner,prot);
    return;
  }
  if(kwIdx!=std::string::npos && (kw=="namespace")){
    parseNamespace(sig,doc,docLine);
    return;
  }
  // function or variable
  int p=findParen(sig);
  if(p>=0){
    // function
    parseFunction(sig,doc,docLine,owner,prot,stop==1);
    return;
  }
  parseVar(sig,doc,docLine,owner,prot,stop>=2,"");
}

void FileParser::parseClass(const std::vector<Tok> &sig, const std::string &doc, int docLine){
  ClassDef *cd=new ClassDef();
  size_t i=0;
  std::string kind="class";
  while(i<sig.size() && !(sig[i].type==0 && (sig[i].text=="class"||sig[i].text=="struct"||sig[i].text=="union"||sig[i].text=="interface"||sig[i].text=="exception"))){
    if(sig[i].text=="friend"||sig[i].text=="template"){ /* skip */ }
    i++;
  }
  if(i<sig.size()){ kind=sig[i].text; i++; }
  // template args?
  std::string targs;
  // name
  std::string name;
  if(i<sig.size() && sig[i].type==0) name=sig[i].text;
  // qualified name for nested classes
  std::string qual=name;
  if(name.empty()) name="<anonymous>";
  cd->name=name;
  cd->kind=kind;
  cd->declLine=peek().line;
  cd->line=docLine;
  cd->relFile=relName;
  cd->file=path;
  cd->documented=!doc.empty();
  // doc
  cd->brief=doc;  // will be split later
  // bases: after ':' up to '{'
  size_t colon=std::string::npos;
  for(size_t k=i;k<sig.size();k++) if(sig[k].text==":"){ colon=k; break; }
  if(colon!=std::string::npos){
    std::vector<std::string> parts;
    std::string cur;
    for(size_t k=colon+1;k<sig.size();k++){
      if(sig[k].text==","){ if(!cur.empty()) parts.push_back(cur); cur=""; continue; }
      if(k>colon+1) cur+=" ";
      cur+=sig[k].text;
    }
    if(!cur.empty()) parts.push_back(cur);
    for(size_t k=0;k<parts.size();k++){
      std::string b=parts[k];
      static const char *acc[]={"public","private","protected","virtual",NULL};
      bool changed=true;
      while(changed){ changed=false;
        for(int q=0;acc[q];q++){ if(strStartsWith(b,std::string(acc[q])+" ")){ b=b.substr(strlen(acc[q])+1); changed=true; } }
      }
      if(!b.empty()) cd->bases.push_back(b);
    }
  }
  classes.push_back(cd);
  // parse body
  if(stop==2){
    next(); // consume '{'
    parseBody(cd,"public",braceDepth+1);
    // consume optional ';'
    if(!atEnd() && peek().text==";") next();
  } else {
    // forward declaration - skip to ';'
    while(!atEnd() && peek().text!=";") next();
    if(!atEnd()) next();
    cd->isForward=true;
    classes.pop_back();
    delete cd;
  }
}

void FileParser::parseNamespace(const std::vector<Tok> &sig, const std::string &doc, int docLine){
  std::string name;
  for(size_t i=0;i<sig.size();i++) if(sig[i].type==0 && sig[i].text!="namespace" && sig[i].text!="inline"){ name=sig[i].text; break; }
  NamespaceDef *nd=new NamespaceDef();
  nd->name=name; nd->qualName=name;
  nd->line=docLine; nd->declLine=peek().line;
  nd->documented=!doc.empty();
  nd->brief=doc;
  nd->file=path; nd->relFile=relName;
  namespaces.push_back(nd);
  if(stop==2){
    next();
    parseBody(NULL,"public",braceDepth+1);
    if(!atEnd() && peek().text==";") next();
  }
}

void FileParser::parseEnum(const std::vector<Tok> &sig, const std::string &doc, int docLine, ClassDef *owner, const std::string &prot){
  EnumDef *ed=new EnumDef();
  size_t i=0;
  while(i<sig.size() && sig[i].text!="enum") i++;
  i++;
  if(i<sig.size() && (sig[i].text=="class"||sig[i].text=="struct")){ ed->isScoped=true; i++; }
