void FileParser::parseEnum(const std::vector<Tok> &sig, const std::string &doc, int docLine, ClassDef *owner, const std::string &prot){
  EnumDef *ed=new EnumDef();
  size_t i=0;
  while(i<sig.size() && sig[i].text!="enum") i++;
  i++;
  if(i<sig.size() && (sig[i].text=="class"||sig[i].text=="struct")){ ed->isScoped=true; i++; }
  if(i<sig.size() && sig[i].type==0) ed->name=sig[i].text;
  ed->qualName=ed->name;
  ed->line=docLine; ed->declLine=peek().line;
  ed->documented=!doc.empty();
  ed->brief=doc;
  ed->protection=prot;
  ed->file=path; ed->relFile=relName;
  // base type after ':'
  size_t ci=std::string::npos;
  for(size_t k=i;k<sig.size();k++) if(sig[k].text==":"){ ci=k; break; }
  if(ci!=std::string::npos){
    std::string bt;
    for(size_t k=ci+1;k<sig.size();k++){ if(k>ci+1) bt+=" "; bt+=sig[k].text; }
    ed->baseType=bt;
  }
  enums.push_back(ed);
  // parse the values
  if(stop==2){
    next(); // '{'
    std::string curDoc=""; int curDocLine=0;
    while(!atEnd()){
      const Tok &t=peek();
      if(t.type==4 && t.text=="}"){ next(); break; }
      if(t.type==4 && t.text==","){ next(); continue; }
      // read value: name [= expr]
      if(t.type!=0){ next(); continue; }
      int vl=0; bool f2=false;
      std::string vd=docFor(t.line,&vl,&f2);
      if(!f2){ // try trailing comment later
      }
      MemberDef *md=mkMember();
      md->kind="enumValue"; md->name=t.text; md->qualName=(owner?owner->name+"::":"")+t.text;
      md->protection=prot;
      md->line=vl; md->declLine=t.line;
      md->file=path; md->relFile=relName;
      md->documented=!vd.empty();
      md->brief=vd;
      md->memberOf=NULL;
      next();
      // initializer
      std::string init;
      if(!atEnd() && peek().text=="="){
        next();
        int d=0;
        while(!atEnd()){
          const Tok &u=peek();
          if(u.type==4 && (u.text=="("||u.text=="["||u.text=="<")) d++;
          else if(u.type==4 && (u.text==")"||u.text=="]")) d--;
          else if(u.type==4 && u.text==">"){ if(d==0) break; d--; }
          else if(u.type==4 && (u.text==","||u.text=="}") && d==0) break;
          init+=u.text; next();
        }
      }
      md->enumValue=init;
      md->enumType=ed->name;
      if(vd==0 && !f2){
        // check for trailing comment on the same line
        int tl=0; bool f3=false;
        std::string td=docFor(t.line+1,&tl,&f3);
        (void)td;
      }
      ed->values.push_back(md);
      members.push_back(md);
    }
    if(!atEnd() && peek().text==";") next();
  } else {
    // enum declaration without body (forward)
    while(!atEnd() && peek().text!=";") next();
    if(!atEnd()) next();
  }
}
