    if(quals[k]=="inline") isInline=true;
    if(quals[k]=="explicit") isExplicit=true;
  }
  std::vector<std::string> tv=tokenizeWS(tail);
  for(size_t k=0;k<tv.size();k++){
    if(tv[k]=="const") isConst=true;
    else if(tv[k]=="override") isOverride=true;
    else if(tv[k]=="noexcept") isNoExcept=true;
    else if(tv[k]=="0") isPure=true;
  }
  MemberDef *md=mkMember();
  md->kind="function";
  md->name=name;
  md->type=type;
  md->args="("+args+")";
  md->qualName=(owner?owner->name+"::":"")+name;
  md->protection=prot;
  md->isConst=isConst; md->isPure=isPure; md->isOverride=isOverride;
  md->isVirtual=isVirtual; md->isStatic=isStatic; md->isInline=isInline; md->isExplicit=isExplicit;
  md->isCtor=(owner && name==owner->name);
  md->isDtor=(owner && !name.empty() && name[0]=='~');
