      int d=0;
      while(i<sig.size()){
        if(sig[i].text=="<") d++;
        else if(sig[i].text==">"){ d--; if(d==0){ ta+=sig[i].text; i++; break; } }
        ta+=sig[i].text; i++;
      }
    }
