    int d=0; std::vector<std::string> plist;
    std::string cur;
    for(size_t k=0;k<s.size();k++){
      char c=s[k];
      if(c=='('||c=='['||c=='<') { d++; cur+=c; continue; }
      if(c==')'||c==']'||c=='>') { d--; cur+=c; continue; }
