  md->isDtor=(owner && !name.empty() && name[0]=='~');
  md->line=docLine; md->declLine=peek().line;
  md->file=path; md->relFile=relName;
  md->documented=!doc.empty();
  md->brief=doc;
  if(owner) md->memberOf=NULL;
  // template args from sig[0..] if template
  if(!sig.empty() && sig[0].text=="template"){
    size_t i=1; std::string ta;
    if(i<sig.size() && sig[i].text=="<"){
      int d=0;
      while(i<sig.size()){
        if(sig[i].text=="<") d++;
        else if(sig[i].text==">"){ d--; if(d==0){ ta+=sig[i].text; i++; break; } }
        ta+=sig[i].text; i++;
      }
    }
    md->templateArgs=ta;
  }
  // params
  {
    std::string s=args;
    int d=0; std::vector<std::string> plist;
    std::string cur;
    for(size_t k=0;k<s.size();k++){
      char c=s[k];
      if(c=='('||c=='['||c=='<') { d++; cur+=c; continue; }
      if(c==')'||c==']'||c=='>') { d--; cur+=c; continue; }
      if(c==','&&d==0){ plist.push_back(cur); cur=""; continue; }
      cur+=c;
    }
    if(!stripWS(cur).empty()||!plist.empty()) plist.push_back(cur);
    for(size_t k=0;k<plist.size();k++){
      std::string ps=stripWS(plist[k]);
      if(ps.empty()) continue;
      ParamInfo pi;
      // split at the last identifier
      std::vector<std::string> toks2=tokenizeWS(ps);
      if(!toks2.empty()){
        std::string pname=toks2.back();
        // strip array suffix
        if(strEndsWith(pname,"]")){ /* keep */ }
        pi.name=pname;
        pi.type=joinStr(std::vector<std::string>(toks2.begin(),toks2.end()-1)," ");
        if(pi.type.empty()) pi.type=pname, pi.name="";
      }
      md->params.push_back(pi);
    }
  }
  members.push_back(md);
  // skip the body if present
  if(stop==2){
    next();
    int d=1;
    while(!atEnd() && d>0){
      const Tok &t=next();
      if(t.type==4 && t.text=="{") d++;
      else if(t.type==4 && t.text=="}") d--;
    }
  }
}

void FileParser::parseVar(const std::vector<Tok> &sig, const std::string &doc, int docLine,
                          ClassDef *owner, const std::string &prot, bool endedWithBrace, const std::string &init){
  (void)endedWithBrace;
  std::string name;
  std::string type;
  std::string initializer=init;
  bool isTypedef=false,isUsing=false;
  std::vector<std::string> quals;
  size_t start=0;
  if(!sig.empty() && sig[0].text=="template"){
    start=1; int d=0;
    while(start<sig.size()){
      if(sig[start].text=="<") d++;
      else if(sig[start].text==">"){ d--; if(d==0){ start++; break; } }
      start++;
    }
  }
  size_t i=start;
  if(i<sig.size() && sig[i].text=="typedef"){ isTypedef=true; i++; }
  else if(i<sig.size() && sig[i].text=="using"){ isUsing=true; i++; }
  // find '=' at top level
  size_t eq=std::string::npos;
  {
    int d=0;
    for(size_t k=i;k<sig.size();k++){
      const Tok &t=sig[k];
      if(t.type==4){ if(t.text=="("||t.text=="["||t.text=="<") d++; else if(t.text==")"||t.text=="]") d--; else if(t.text==">"){ if(d==0){ eq=k; break; } d--; } else if(t.text=="="&&d==0){ eq=k; break; } }
    }
  }
  size_t nameEnd = (eq==std::string::npos)?sig.size():eq;
  // the name is the last identifier before nameEnd
  std::vector<std::string> parts;
  for(size_t k=i;k<nameEnd;k++){
    const Tok &t=sig[k];
    if(t.type==4 && (t.text=="::"||t.text=="*"||t.text=="&")) { parts.push_back(t.text); continue; }
    parts.push_back(t.text);
  }
  while(!parts.empty() && isQual(parts[0])){ quals.push_back(parts[0]); parts.erase(parts.begin()); }
  if(!parts.empty()){ name=parts.back(); parts.pop_back(); }
  // strip array brackets from the name
  size_t br=name.find('[');
  if(br!=std::string::npos) name=name.substr(0,br);
  type=joinStr(parts," ");
  if(isUsing){
    // using NAME = TYPE;
    if(eq!=std::string::npos){ type=sigText(sig,eq+1); }
  }
  if(eq!=std::string::npos && !isUsing) initializer=sigText(sig,eq+1);
  MemberDef *md=mkMember();
  md->kind="variable";
  md->name=name;
  md->type=type;
  md->qualName=(owner?owner->name+"::":"")+name;
  md->protection=prot;
  md->initializer=initializer;
  md->isTypedef=isTypedef; md->isUsing=isUsing;
  for(size_t k=0;k<quals.size();k++){ if(quals[k]=="static") md->isStatic=true; }
  md->line=docLine; md->declLine=peek().line;
  md->file=path; md->relFile=relName;
  md->documented=!doc.empty();
  md->brief=doc;
  members.push_back(md);
}

MemberDef *FileParser::mkMember(){ return new MemberDef(); }

void FileParser::run(){
  // split the source into top-level declarations
  while(!atEnd()){
    const Tok &t=peek();
    if(t.type==4 && t.text==";"){ next(); continue; }
    if(t.type==5){ next(); continue; }   // preprocessor line - handle defines
    if(t.type==4 && t.text=="}"){ next(); continue; }
    parseDeclaration(NULL,"public",NULL);
  }
  // handle #define macros
}
