    if(s[i]=='_'){
      size_t j=i+1;
      while(j<s.size() && s[j]!='_') j++;
      if(j<s.size() && j>i+1){
        out+="<em>"+mdInline(s.substr(i+1,j-i-1))+"</em>";
        i=j+1; continue;
      }
    }
    out+=s[i]; i++;
  }
  return out;
}

