static std::string escapeTxt(const std::string &s){
  std::string o;
  for(size_t i=0;i<s.size();i++){
    unsigned char c=s[i];
    switch(c){
      case '<': o+="&lt;"; break;
      case '>': o+="&gt;"; break;
      case '&': o+="&amp;"; break;
      case '"': o+="&quot;"; break;
      default: o+=(char)c;
