struct SectionItem {
    std::string cls;      // dl class
    std::string label;    // dt label
    std::string text;
    std::string name;     // for param-like
    bool table=false;
};

struct DocRender {
    std::string out;
    std::vector<std::string> paragraphs;    // rendered <p> blocks (flushed as needed)
    std::vector<SectionItem> sections;
    bool curOpen=false;
    std::string cur;
    bool anyPara=false;

    void flushPara(){
        if(cur.empty()) return;
        paragraphs.push_back("<p>"+cur+"</p>");
        cur.clear();
        curOpen=false;
        anyPara=true;
    }
    void flushAll(){
        flushPara();
        for(size_t i=0;i<paragraphs.size();i++){ out+=paragraphs[i]; out+="\n"; }
        paragraphs.clear();
        for(size_t i=0;i<sections.size();i++){
            const SectionItem &s=sections[i];
            out+="<dl class=\""+s.cls+"\"><dt>"+s.label+"</dt><dd>";
            out+=s.text;
            out+="</dd>\n</dl>\n";
        }
        sections.clear();
    }
};

static std::string paramTableHtml(const std::vector<SectionItem> &items, const char *tblcls){
    std::string o;
    o+="\n  <table class=\""+std::string(tblcls)+"\">\n";
    for(size_t i=0;i<items.size();i++){
        o+="    <tr><td class=\"paramname\">"+items[i].name+"</td><td>"+items[i].text+"</td></tr>\n";
    }
    o+="  </table>\n  ";
    return o;
}

// -------------------------------------------------------------- doc renderer

static std::string renderInlineText(const std::string &s, bool markdown=true){
  std::string t=escapeTxt(s);
  if(markdown&&mdEnabled) t=mdInline(t);
  return t;
}

struct DocText {
    std::string text;      // text with markup commands already converted
};

// Parse a documentation string into HTML.  text is the raw (normalized) doc content.
std::string docToHtml(const std::string &rawText, bool repeatBrief){
    std::string text=rawText;
    if(repeatBrief){
        // handled by the caller; here we simply render
    }
    DocRender r;
    std::vector<std::string> lines=splitStr(text,"\n");
    std::vector<std::string> cmdLines;   // collected for section commands
    std::string curCmd;
    std::string curArg;
    bool inCode=false;
    std::string codeLang;
    std::string codeText;

    auto flushSection = [&](const std::string &cmd, const std::string &arg){
        SectionItem s;
        if(cmd=="param"||cmd=="tparam"){
            s.cls=(cmd=="param")?"params":"tparams";
            s.label=(cmd=="param")?"Parameters":"Template Parameters";
            s.table=true;
            // split the first word
            std::string a=stripLeadingWS(arg);
            size_t sp=a.find_first_of(" \t");
            if(sp!=std::string::npos){ s.name=a.substr(0,sp); s.text=renderInlineText(stripWS(a.substr(sp+1)))+" "; }
            else { s.name=a; }
        } else if(cmd=="retval"){
            s.cls="retval"; s.label="Return values"; s.table=true;
