          else curItems[i].text=renderInline(curItems[i].text);
          r.sections.push_back(curItems[i]);
        }
        curItems.clear();
        startSection(cmd,arg);
        continue;
      }
      // inline command -> just render the line for now
      r.addText(renderInline(line));
      if(li+1<lines.size()) r.cur+=" ";
      continue;
    }
    if(pending){
      curArg+=(curArg.empty()?"":" ")+stripWS(line);
    } else {
      r.addText(renderInline(stripWS(line)));
      if(li+1<lines.size()) r.cur+=" ";
    }
  }
  if(pending){
    for(size_t i=0;i<curItems.size();i++){
      if(curItems[i].table) curItems[i].text=sectionHtml(curItems,curItems[i].cls=="params"?"params":(curItems[i].cls=="tparams"?"tparams":"retval"));
      else curItems[i].text=renderInline(curItems[i].text);
      r.sections.push_back(curItems[i]);
    }
  }
  r.endPara();
  r.endSections();
  return r.out;
}

