std::vector<std::string> normalizeDocLines(const std::string &raw){
  std::vector<std::string> out;
  std::vector<std::string> lines=splitStr(raw,"\n");
  for(size_t i=0;i<lines.size();i++){
    std::string l=stripLeadingWS(lines[i]);
    if(!l.empty() && l[0]=='*'){
      l=l.substr(1);
      if(!l.empty() && (l[0]==' '||l[0]=='\t')) l=l.substr(1);
    }
    out.push_back(l);
  }
  return out;
}

static const char *SECTION_CMDS[]={"param","tparam","return","retval","note","warning","attention","bug",
  "todo","test","deprecated","author","authors","version","since","date","pre","post","invariant",
  "exception","exceptions","see","sa","arg","xrefitem","requires","copyright","internal",
  "remark","remarks","details",NULL};
static const char *CODE_CMDS[]={"code","verbatim","htmlonly","dot","msc","startuml","latexonly","manonly","xmlonly","rtfonly",NULL};
static const char *ENDCODE_CMDS[]={"endcode","endverbatim","endhtmlonly","enddot","endmsc","enduml","endlatexonly","endmanonly","endxmlonly","endrtfonly",NULL};

static bool inList(const char **list,const std::string &s){
  for(int i=0;list[i];i++) if(s==list[i]) return true;
  return false;
}

static std::string mdInline(const std::string &s){
  std::string out; size_t i=0;
  while(i<s.size()){
    if(s[i]=='`'){
      size_t j=i+1; while(j<s.size() && s[j]!='`') j++;
      if(j<s.size()){ out+="<span class=\"tt\">"+s.substr(i+1,j-i-1)+"</span>"; i=j+1; continue; }
    }
    if(i+1<s.size() && s[i]=='*' && s[i+1]=='*'){
      size_t j=i+2; while(j+1<s.size() && !(s[j]=='*'&&s[j+1]=='*')) j++;
      if(j+1<s.size() && j>i+2){ out+="<b>"+mdInline(s.substr(i+2,j-i-2))+"</b>"; i=j+2; continue; }
    }
    if(s[i]=='*'){
      size_t j=i+1; while(j<s.size() && s[j]!='*') j++;
      if(j<s.size() && j>i+1){ out+="<em>"+mdInline(s.substr(i+1,j-i-1))+"</em>"; i=j+1; continue; }
    }
    if(s[i]=='_'){
      size_t j=i+1; while(j<s.size() && s[j]!='_') j++;
      if(j<s.size() && j>i+1){ out+="<em>"+mdInline(s.substr(i+1,j-i-1))+"</em>"; i=j+1; continue; }
    }
    out+=s[i]; i++;
  }
  return out;
}

static std::string escapeTxt(const std::string &s){
  std::string o;
  for(size_t i=0;i<s.size();i++){
    unsigned char c=s[i];
    switch(c){
      case '<': o+="&lt;"; break;
      case '>': o+="&gt;"; break;
      case '&': o+="&amp;"; break;
      case '"': o+="&quot;"; break;
      default: o+=(char)c;
    }
  }
  return o;
}
static std::string renderInline(const std::string &s){ std::string t=escapeTxt(s); return mdInline(t); }

struct Section { std::string cls,label,text,name; bool table=false; };

struct Renderer {
    std::string out;
    std::string cur;             // current paragraph html
    bool havePara=false;
    std::vector<Section> sections;
    void endPara(){
      if(!havePara) return;
      out+="<p>"+cur+"</p>\n";
      cur.clear(); havePara=false;
    }
    void addText(const std::string &t){ cur+=t; havePara=true; }
    void endSections(){
      for(size_t i=0;i<sections.size();i++){
        Section &s=sections[i];
        out+="<dl class=\""+s.cls+"\"><dt>"+s.label+"</dt><dd>";
        out+=s.text;
        out+="</dd>\n</dl>\n";
      }
      sections.clear();
    }
};

static std::string sectionHtml(const std::vector<Section> &items,const char *tbl){
  std::string o="\n  <table class=\""+std::string(tbl)+"\">\n";
  for(size_t i=0;i<items.size();i++)
    o+="    <tr><td class=\"paramname\">"+items[i].name+"</td><td>"+items[i].text+"</td></tr>\n";
  o+="  </table>\n  ";
  return o;
}

// split a doc text into brief and rest
DocParts splitDoc(const std::string &text,bool javaAutoBrief){
  DocParts p;
  std::vector<std::string> lines=splitStr(text,"\n");
  bool inBrief=false;
  bool firstParaDone=false;
  std::string briefTxt;
  std::string restTxt;
  for(size_t i=0;i<lines.size();i++){
    std::string line=lines[i];
    bool isBlank=stripWS(line).empty();
    if(!inBrief){
      if(!isBlank && (line[0]=='@'||line[0]=='\\')){
        size_t sp=1;
        while(sp<line.size() && (isalnum((unsigned char)line[sp])||line[sp]=='_'||line[sp]==':')) sp++;
        std::string cmd=line.substr(1,sp-1);
        if(cmd=="brief"){ inBrief=true; p.hasBriefCmd=true; briefTxt+=line.substr(sp)+"\n"; continue; }
        if(javaAutoBrief && !firstParaDone){ firstParaDone=true; inBrief=true; briefTxt+=line+"\n"; continue; }
      }
      if(isBlank){ firstParaDone=true; }
      restTxt+=line+"\n";
      continue;
    }
    // in brief
    if(isBlank && !p.hasBriefCmd){ inBrief=false; }
    else if(isBlank && p.hasBriefCmd){ inBrief=false; }
    if(!inBrief) restTxt+=line+"\n";
    else briefTxt+=line+"\n";
  }
  // normalize: strip the leading space of each line
  std::vector<std::string> bl=normalizeDocLines(briefTxt);
  std::string b2;
  for(size_t i=0;i<bl.size();i++){ b2+=bl[i]; if(i+1<bl.size()) b2+="\n"; }
  std::vector<std::string> rl=normalizeDocLines(restTxt);
  std::string r2;
  for(size_t i=0;i<rl.size();i++){ r2+=rl[i]; if(i+1<rl.size()) r2+="\n"; }
  p.brief=b2; p.rest=r2;
  // if no brief command, the brief is the first paragraph
  return p;
}

std::string docToHtml(const std::string &text,bool repeatBrief){
  Renderer r;
  std::vector<std::string> lines=splitStr(text,"\n");
  bool inCode=false;
  std::string codeText;
  std::string curSection;
  std::string curArg;
  std::vector<Section> curItems;
  bool pending=false;

  auto startSection=[&](const std::string &cmd,const std::string &arg){
    Section s;
    if(cmd=="param"||cmd=="tparam"||cmd=="retval"){
      s.table=true;
      s.cls=(cmd=="param")?"params":(cmd=="tparam"?"tparams":"retval");
      s.label=(cmd=="param")?"Parameters":(cmd=="tparam"?"Template Parameters":"Return values");
      std::string a=stripLeadingWS(arg);
      size_t sp=a.find_first_of(" \t");
      if(sp!=std::string::npos){ s.name=a.substr(0,sp); curArg=stripWS(a.substr(sp+1)); }
      else { s.name=a; curArg=""; }
    } else {
      if(cmd=="return"){ s.cls="section return"; s.label="Returns"; }
      else if(cmd=="note"){ s.cls="section note"; s.label="Note"; }
      else if(cmd=="warning"){ s.cls="section warning"; s.label="Warning"; }
      else if(cmd=="attention"){ s.cls="section attention"; s.label="Attention"; }
      else if(cmd=="bug"){ s.cls="section bug"; s.label="Bug"; }
      else if(cmd=="todo"){ s.cls="section todo"; s.label="Todo"; }
      else if(cmd=="test"){ s.cls="section test"; s.label="Test"; }
      else if(cmd=="deprecated"){ s.cls="section deprecated"; s.label="Deprecated"; }
      else if(cmd=="author"||cmd=="authors"){ s.cls="section author"; s.label="Author"; }
      else if(cmd=="version"){ s.cls="section version"; s.label="Version"; }
      else if(cmd=="since"){ s.cls="section since"; s.label="Since"; }
      else if(cmd=="date"){ s.cls="section date"; s.label="Date"; }
      else if(cmd=="pre"){ s.cls="section pre"; s.label="Precondition"; }
      else if(cmd=="post"){ s.cls="section post"; s.label="Postcondition"; }
      else if(cmd=="invariant"){ s.cls="section invariant"; s.label="Invariant"; }
      else if(cmd=="exception"||cmd=="exceptions"){ s.cls="section exception"; s.label="Exceptions"; }
      else if(cmd=="see"||cmd=="sa"){ s.cls="section see"; s.label="See also"; }
      else if(cmd=="arg"){ s.cls="section arg"; s.label="Arguments"; }
      else if(cmd=="remark"||cmd=="remarks"){ s.cls="section remark"; s.label="Remarks"; }
      else if(cmd=="requires"){ s.cls="section requires"; s.label="Requires"; }
      else if(cmd=="copyright"){ s.cls="section copyright"; s.label="Copyright"; }
      else if(cmd=="internal"){ s.cls="section internal"; s.label="Internal"; }
      else if(cmd=="details"){ s.cls="section details"; s.label=""; }
      else { s.cls="section "+cmd; s.label=upperStr(cmd.substr(0,1))+cmd.substr(1); }
      curArg=stripWS(arg);
    }
    curItems.push_back(s);
    pending=true;
  };

  for(size_t li=0;li<lines.size();li++){
    std::string line=lines[li];
    if(inCode){
      std::string cmd;
      if(line.size()>1&&(line[0]=='@'||line[0]=='\\')){
        size_t sp=1; while(sp<line.size() && (isalnum((unsigned char)line[sp])||line[sp]=='_')) sp++;
        cmd=line.substr(1,sp-1);
      }
      if(inList(ENDCODE_CMDS,cmd)){
        inCode=false;
        r.endPara(); r.endSections();
        r.out+="<div class=\"fragment\">";
        std::vector<std::string> cl=splitStr(codeText,"\n");
        for(size_t k=0;k<cl.size();k++){ r.out+="<div class=\"line\">"+escapeTxt(cl[k])+"</div>\n"; }
        r.out+="</div><!-- fragment -->\n";
        codeText.clear();
        continue;
      }
      codeText+=line; codeText+="\n";
      continue;
    }
    bool blank=stripWS(line).empty();
    if(blank){
      if(pending && curArg.empty()){
        // flush section
        for(size_t i=0;i<curItems.size();i++){
          if(curItems[i].table) curItems[i].text=sectionHtml(curItems,curItems[i].cls=="params"?"params":(curItems[i].cls=="tparams"?"tparams":"retval"));
          else curItems[i].text=renderInline(curItems[i].text);
          r.sections.push_back(curItems[i]);
        }
        curItems.clear(); pending=false; curArg.clear();
      } else if(pending){
        curArg+=" ";
      } else {
        r.endPara();
      }
      continue;
    }
    if(line.size()>1 && (line[0]=='@'||line[0]=='\\')){
      size_t sp=1;
      while(sp<line.size() && (isalnum((unsigned char)line[sp])||line[sp]=='_'||line[sp]==':')) sp++;
      std::string cmd=line.substr(1,sp-1);
      std::string arg=line.substr(sp);
      if(inList(CODE_CMDS,cmd)){ r.endPara(); inCode=true; codeText.clear(); continue; }
      if(inList(ENDCODE_CMDS,cmd)) continue;
      if(cmd=="brief") continue;
      if(cmd=="internal"||cmd=="cond"||cmd=="endcond"||cmd=="if"||cmd=="endif"||cmd=="hide"||cmd=="show") continue;
      if(inList(SECTION_CMDS,cmd)){
        // flush pending section first
        for(size_t i=0;i<curItems.size();i++){
          if(curItems[i].table) curItems[i].text=sectionHtml(curItems,curItems[i].cls=="params"?"params":(curItems[i].cls=="tparams"?"tparams":"retval"));
          else curItems[i].text=renderInline(curItems[i].text);
          r.sections.push_back(curItems[i]);
        }
        curItems.clear();
        startSection(cmd,arg);
        continue;
      }
      // inline command -> just render the line for now
      r.addText(renderInline(line));
      if(li+1<lines.size()) r.cur+=" ";
      continue;
    }
    if(pending){
      curArg+=(curArg.empty()?"":" ")+stripWS(line);
    } else {
      r.addText(renderInline(stripWS(line)));
      if(li+1<lines.size()) r.cur+=" ";
    }
  }
  if(pending){
    for(size_t i=0;i<curItems.size();i++){
      if(curItems[i].table) curItems[i].text=sectionHtml(curItems,curItems[i].cls=="params"?"params":(curItems[i].cls=="tparams"?"tparams":"retval"));
      else curItems[i].text=renderInline(curItems[i].text);
      r.sections.push_back(curItems[i]);
    }
  }
  r.endPara();
  r.endSections();
  return r.out;
}

