// -------------------------------------------------------------- substitutions
static std::string substVars(const std::string &t, const std::map<std::string,std::string> &v){
  std::string out;
  size_t i=0;
  while(i<t.size()){
    if(t[i]=='$'){
      size_t j=i+1;
      while(j<t.size() && (isalnum((unsigned char)t[j])||t[j]=='_'||t[j]=='^')) j++;
      std::string key=t.substr(i+1,j-i-1);
