        if(it!=v.end()){ out+=it->second; i=j; continue; }
      }
      std::map<std::string,std::string>::const_iterator it=v.find(key);
      if(it!=v.end()){ out+=it->second; i=j; continue; }
      out+=t[i]; i++;
      continue;
    }
    out+=t[i]; i++;
  }
  return out;
}

// Handle <!--BEGIN X--> ... <!--END X--> conditionals
static std::string condBlocks(const std::string &t, const std::map<std::string,bool> &cond){
  std::string out;
  size_t i=0;
  while(i<t.size()){
    size_t b=t.find("<!--BEGIN ",i);
    if(b==std::string::npos){ out+=t.substr(i); break; }
    out+=t.substr(i,b-i);
    size_t e=t.find("-->",b);
    if(e==std::string::npos){ out+=t.substr(b); break; }
    std::string key=t.substr(b+10,e-(b+10));
    size_t endKey=t.find("<!--END "+key+"-->",e);
    if(endKey==std::string::npos){ out+=t.substr(b); break; }
    std::string inner=t.substr(e+3,endKey-b-13);
    bool on=false;
    if(key.size()>0&&key[0]=='!'){
      std::map<std::string,bool>::const_iterator it=cond.find(key.substr(1));
      on=(it==cond.end())?false:!it->second;
    } else {
      std::map<std::string,bool>::const_iterator it=cond.find(key);
      on=(it!=cond.end())?it->second:false;
    }
    if(on) out+=condBlocks(inner,cond);
    i=endKey+strlen("<!--END ")+key.size()+3;
  }
  return out;
}

static std::string applyTemplate(const std::string &tpl, const std::map<std::string,std::string> &vars,
                                 const std::map<std::string,bool> &cond){
  std::string t=condBlocks(tpl,cond);
  t=substVars(t,vars);
  return t;
}
