static std::string substVars(const std::string &t, const std::map<std::string,std::string> &v){
  std::string out;
  size_t i=0;
  while(i<t.size()){
    if(t[i]=='$'){
      size_t j=i+1;
      while(j<t.size() && (isalnum((unsigned char)t[j])||t[j]=='_'||t[j]=='^')) j++;
      std::string key=t.substr(i+1,j-i-1);
      if(key.size()>0 && key[key.size()-1]=='^'){
        std::string base=key.substr(0,key.size()-1);
        std::map<std::string,std::string>::const_iterator it=v.find(base);
        if(it!=v.end()){ out+=it->second; i=j; continue; }
      }
      std::map<std::string,std::string>::const_iterator it=v.find(key);
      if(it!=v.end()){ out+=it->second; i=j; continue; }
      out+=t[i]; i++;
