  return p.brief;
}
static std::string detailedOf(const std::string &raw, bool repeatBrief){
  DocParts p=splitDoc(raw,false);
  std::string t=p.rest;
  if(repeatBrief && !p.brief.empty()) t=p.brief+"\n"+p.rest;
  return docToHtml(t);
}
static std::string briefContentOf(const std::string &raw){
  DocParts p=splitDoc(raw,false);
  std::string h=docToHtml(p.brief);
  // strip the <p> and </p>\n wrapper
  if(strStartsWith(h,"<p>") && strEndsWith(h,"</p>\n")) return h.substr(3,h.size()-7);
  return h;
}
static std::string firstSentenceOf(const std::string &raw){
  DocParts p=splitDoc(raw,false);
  std::string b=p.brief;
  // strip trailing newline
  while(!b.empty() && (b[b.size()-1]=='\n'||b[b.size()-1]==' ')) b.resize(b.size()-1);
  // remove trailing period
  if(!b.empty() && b[b.size()-1]=='.') b.resize(b.size()-1);
  return b+" ";
}
