// --------------------------------------------------------------- class page

static const char *groupTitle(const std::string &prot,const std::string &kind,bool &isFunc){
  std::string p=prot;
  if(p=="signals"){ isFunc=true; return "Signals"; }
  if(strEndsWith(p,"-slots")){ isFunc=true; return (p+"").c_str(); }
  if(kind=="function"){ isFunc=true;
    if(p=="public") return "Public Member Functions";
    if(p=="protected") return "Protected Member Functions";
    if(p=="private") return "Private Member Functions";
    if(p=="public-slots") return "Public Slots";
    if(p=="protected-slots") return "Protected Slots";
    if(p=="private-slots") return "Private Slots";
    if(p=="signals") return "Signals";
    return "Member Functions";
  }
  isFunc=false;
  if(p=="public") return "Public Attributes";
  if(p=="protected") return "Protected Attributes";
  if(p=="private") return "Private Attributes";
  return "Member Data";
}
static std::string groupId(const std::string &prot,const std::string &kind,bool isFunc){
  std::string p=prot;
  if(isFunc){
    if(p=="public") return "pub-methods";
    if(p=="protected") return "prot-methods";
    if(p=="private") return "pri-methods";
    if(p=="public-slots") return "pub-slots";
    if(p=="protected-slots") return "prot-slots";
    if(p=="private-slots") return "pri-slots";
    if(p=="signals") return "signals";
  } else {
    if(p=="public") return "pub-attribs";
    if(p=="protected") return "prot-attribs";
    if(p=="private") return "pri-attribs";
  }
  return p;
}

static std::string memItemLeft(MemberDef *m){
  std::string o;
  if(!m->type.empty()) o+=htmlEscape(m->type)+"&#160;";
  else o+="&#160;";
  return o;
}

static std::string memItemRight(MemberDef *m, const std::string &url){
  std::string o;
  o+="<a class=\"el\" href=\""+url+"\">"+htmlEscape(m->name)+"</a>";
  if(m->kind=="function"){ o+=" "+htmlEscape(m->args); }
  else if(!m->initializer.empty() && m->kind=="enumValue"){ }
  else if(!m->initializer.empty()){ o+=" "+htmlEscape(m->initializer); }
  if(m->isConst && m->kind=="function") o+=" const";
  return o;
}

