static std::string classPageContent(ClassDef *cd){
  std::string o;
  // brief description
  std::string braw=briefOf(cd);
  if(!braw.empty()){
    std::string bc=briefContentOf(cd->brief);
    o+="\n<p>"+bc;
    DocParts dp=splitDoc(cd->brief,false);
    if(!dp.rest.empty()) o+=" \n <a href=\"#details\">More...</a>";
    o+="</p>\n";
  }
  // brief member table
  std::vector<std::pair<std::string,std::string> > groups;  // (id,title)
  std::map<std::string,std::vector<MemberDef*> > byGroup;
  for(size_t i=0;i<cd->members.size();i++){
    MemberDef *m=cd->members[i];
    if(!m->documented) continue;
    if(m->kind=="enumValue") continue;
    if(m->isCtor||m->isDtor){ }
    bool isFunc=(m->kind=="function");
    std::string gid=groupId(m->protection,m->kind,isFunc);
    std::string gtitle=groupTitle(m->protection,m->kind,isFunc);
    if(byGroup.find(gid)==byGroup.end()) groups.push_back(std::make_pair(gid,gtitle));
    byGroup[gid].push_back(m);
  }
  if(!groups.empty()){
    o+="<table class=\"memberdecls\">\n";
    for(size_t g=0;g<groups.size();g++){
      const std::string &gid=groups[g].first;
      o+="<tr class=\"heading\"><td colspan=\"2\"><h2 id=\"header-"+gid+"\" class=\"groupheader\"><a id=\""+gid+"\" name=\""+gid+"\"></a>\n";
      o+=htmlEscape(groups[g].second)+"</h2></td></tr>\n";
      std::vector<MemberDef*> &v=byGroup[gid];
      for(size_t i=0;i<v.size();i++){
        MemberDef *m=v[i];
        o+="<tr class=\"memitem:"+m->anchor+"\" id=\"r_"+m->anchor+"\">";
        o+="<td class=\"memItemLeft\">"+memItemLeft(m)+"</td>";
        o+="<td class=\"memItemRight\">"+memItemRight(m,"#"+m->anchor)+"</td></tr>\n";
        std::string bd=briefContentOf(m->brief);
        if(!bd.empty()){
          o+="<tr class=\"memdesc:"+m->anchor+"\"><td class=\"mdescLeft\">&#160;</td><td class=\"mdescRight\">"+bd+" <br /></td></tr>\n";
        }
      }
    }
    o+="</table>\n";
  }
  // detailed description
  DocParts dp=splitDoc(cd->brief,false);
  std::string det=detailedOf(cd->brief,true);
  o+="<a name=\"details\" id=\"details\"></a><h2 id=\"header-details\" class=\"groupheader\">Detailed Description</h2>\n";
  o+="<div class=\"textblock\">"+det+"</div>";
  // detailed member sections
  std::vector<MemberDef*> ctors,funcs,vars;
  for(size_t i=0;i<cd->members.size();i++){
    MemberDef *m=cd->members[i];
    if(!m->documented) continue;
    if(m->kind=="enumValue") continue;
    if(m->isCtor||m->isDtor) ctors.push_back(m);
    else if(m->kind=="function") funcs.push_back(m);
    else vars.push_back(m);
  }
  if(!ctors.empty()){
    o+="<a name=\"doc-constructors\" id=\"doc-constructors\"></a><h2 id=\"header-doc-constructors\" class=\"groupheader\">Constructor &amp; Destructor Documentation</h2>\n";
    for(size_t i=0;i<ctors.size();i++) writeMemberDoc(o,ctors[i],cd,"");
  }
  if(!funcs.empty()){
    o+="<a name=\"doc-func-members\" id=\"doc-func-members\"></a><h2 id=\"header-doc-func-members\" class=\"groupheader\">Member Function Documentation</h2>\n";
    for(size_t i=0;i<funcs.size();i++) writeMemberDoc(o,funcs[i],cd,"");
  }
  if(!vars.empty()){
    o+="<a name=\"doc-member-members\" id=\"doc-member-members\"></a><h2 id=\"header-doc-member-members\" class=\"groupheader\">Member Data Documentation</h2>\n";
    for(size_t i=0;i<vars.size();i++) writeMemberDoc(o,vars[i],cd,"");
  }
  // used files
  o+="<hr/>The documentation for this class was generated from the following file:<ul>\n";
  o+="<li><b>"+htmlEscape(baseNameOf(cd->file))+"</b></li>\n";
  o+="</ul>\n";
  return o;
}
