// ------------------------------------------------------------------ file writer
static std::set<std::string> g_written;
static void writeFileIf(const std::string &name,const std::string &content){
  if(g_written.count(name)) return;
  g_written.insert(name);
  FILE *f=fopen(name.c_str(),"wb");
  if(!f) return;
  fwrite(content.data(),1,content.size(),f);
  fclose(f);
}

static std::string classFileName(ClassDef *cd){
  std::string o="class";
  // prefix by scope
  std::string q=cd->qualName;
  std::vector<std::string> parts=splitStr(q,"::");
  for(size_t i=0;i<parts.size();i++){ if(i) o+="_"; o+=parts[i]; }
  return o+".html";
}

void generateHtml(const Config &cfg, const std::vector<std::string> &files){
  C=(Config*)&cfg;
  std::string outdir=cfg.str("OUTPUT_DIRECTORY");
  if(outdir.empty()) outdir=".";
  if(!isAbsolutePath(outdir)) outdir=getcwdStr()+"/"+outdir;
  std::string hdir=outdir+"/"+cfg.str("HTML_OUTPUT");
  if(!makeDirs(hdir)){ errorExit("Cannot create directory "+hdir); return; }
  // static assets
  writeFileIf(hdir+"/doxygen.css",tplData("doxygen.css"));
  writeFileIf(hdir+"/tabs.css",tplData("html_tabs.css"));
  writeFileIf(hdir+"/doxygen.svg",tplData("html_doxygen.svg"));
  writeFileIf(hdir+"/clipboard.js",tplData("html_clipboard.js"));
  writeFileIf(hdir+"/cookie.js",tplData("html_cookie.js"));
  writeFileIf(hdir+"/dynsections.js",tplData("html_dynsections.js"));
  writeFileIf(hdir+"/menu.js",tplData("html_menu.js"));
  writeFileIf(hdir+"/navtree.css",tplData("html_navtree.css"));
  writeFileIf(hdir+"/navtree.js",tplData("html_navtree.js"));
  writeFileIf(hdir+"/search/search.css",tplData("html_search/search.css"));
  writeFileIf(hdir+"/search/search.js",tplData("html_search/search.js"));
  // menudata / navtree data / navtreeindex
  g_written.clear();
}
