// ------------------------------------------------------------- nav tree data

struct NavNode {
    std::string name;
    std::string url;
    std::string childrenVar;   // if set, the children are in an external js var
    std::vector<NavNode*> children;
    NavNode *parent=NULL;
};

static std::string navTreeJson(NavNode *n,int depth,bool topLevel){
  std::string ind; for(int i=0;i<depth;i++) ind+="  ";
  std::string o;
  o+=ind+"[ \""+n->name+"\", \""+n->url+"\", ";
  if(!n->childrenVar.empty()) o+=n->childrenVar;
  else if(n->children.empty()) o+="null";
  else {
    o+="[\n";
    for(size_t i=0;i<n->children.size();i++){
      o+=navTreeJson(n->children[i],depth+1,false);
      if(i+1<n->children.size()) o+=",\n";
      else o+="\n";
    }
    o+=ind+"  ]";
  }
  o+=" ]";
  return o;
}

static std::string menuJson(NavNode *n,int depth){
  std::string ind; for(int i=0;i<depth;i++) ind+="  ";
  std::string o;
  o+="{text:\""+n->name+"\",url:\""+n->url+"\"";
  if(!n->children.empty()){
    o+=",children:[\n";
    for(size_t i=0;i<n->children.size();i++){
      o+=ind+"  "+menuJson(n->children[i],depth+1);
      if(i+1<n->children.size()) o+=",\n"; else o+="\n";
    }
    o+=ind+"]}";
  }
  o+="}";
  return o;
}

static void collectIndex(NavNode *n, const std::vector<int> &path, std::map<std::string,std::vector<int> > &idx){
  if(!n->url.empty()){
    std::vector<int> p=path;
    idx[n->url]=p;
  }
  std::vector<int> p2=path;
  if(!path.empty()||true){
    for(size_t i=0;i<n->children.size();i++){
      std::vector<int> c=p2;
      if(p2.empty()) c.push_back(0);
      c.push_back((int)i);
      collectIndex(n->children[i],c,idx);
    }
  }
}

