static std::string memberUrl(MemberDef *m, const std::string &fileBase){
  return fileBase+".html#"+m->anchor;
}

void buildModel(const Config &cfg,const std::vector<std::string> &files){
  for(size_t i=0;i<files.size();i++){
    FileParser *fp=new FileParser(files[i],baseNameOf(files[i]));
    fp->run();
    FileEntry *fe=new FileEntry();
    fe->path=files[i]; fe->name=baseNameOf(files[i]);
    fe->docName=fileDocName(files[i]);
    fe->documented=fp->fileDocumented;
    fe->brief=fp->fileBrief; fe->detailed=fp->fileDetailed;
    fe->classes=fp->classes; fe->enums=fp->enums; fe->members=fp->members;
    fe->namespaces=fp->namespaces;
    M.files.push_back(fe);
    for(size_t k=0;k<fp->classes.size();k++){
      ClassDef *cd=fp->classes[k];
      cd->anchor="";
      M.classes.push_back(cd);
    }
    for(size_t k=0;k<fp->enums.size();k++) M.enums.push_back(fp->enums[k]);
    for(size_t k=0;k<fp->members.size();k++) M.members.push_back(fp->members[k]);
    for(size_t k=0;k<fp->namespaces.size();k++) M.namespaces.push_back(fp->namespaces[k]);
  }
  // anchors
  for(size_t i=0;i<M.classes.size();i++){
    ClassDef *cd=M.classes[i];
    DocParts p=splitDoc(cd->brief,false);
    cd->documented=!p.brief.empty();
    for(size_t k=0;k<cd->members.size();k++){
      MemberDef *m=cd->members[k];
      DocParts p2=splitDoc(m->brief,false);
      m->documented=!p2.brief.empty();
      m->anchor=md5hex(m->qualName+m->args);
    }
  }
  for(size_t i=0;i<M.enums.size();i++){
    EnumDef *ed=M.enums[i];
    DocParts p=splitDoc(ed->brief,false);
    ed->documented=!p.brief.empty();
    for(size_t k=0;k<ed->values.size();k++){
      MemberDef *m=ed->values[k];
      DocParts p2=splitDoc(m->brief,false);
      m->documented=!p2.brief.empty();
      m->anchor=md5hex(m->qualName);
    }
  }
  for(size_t i=0;i<M.members.size();i++){
    MemberDef *m=M.members[i];
    if(m->kind=="enumValue") continue;
    DocParts p=splitDoc(m->brief,false);
    m->documented=!p.brief.empty();
    if(m->anchor.empty()) m->anchor=md5hex(m->qualName+m->args);
  }
}

void generateHtml(const Config &cfg, const std::vector<std::string> &files){
  C=(Config*)&cfg;
  buildModel(cfg,files);
  std::string outdir=cfg.str("OUTPUT_DIRECTORY");
  if(outdir.empty()) outdir=".";
  if(!isAbsolutePath(outdir)) outdir=getcwdStr()+"/"+outdir;
  std::string hdir=outdir+"/"+cfg.str("HTML_OUTPUT");
  if(!makeDirs(hdir)){ errorExit("Cannot create directory "+hdir); return; }
  // static assets
  writeFileIf(hdir+"/doxygen.css",tplData("doxygen.css"));
  writeFileIf(hdir+"/tabs.css",tplData("html_tabs.css"));
  writeFileIf(hdir+"/doxygen.svg",tplData("html_doxygen.svg"));
  writeFileIf(hdir+"/clipboard.js",tplData("html_clipboard.js"));
  writeFileIf(hdir+"/cookie.js",tplData("html_cookie.js"));
  writeFileIf(hdir+"/dynsections.js",tplData("html_dynsections.js"));
  writeFileIf(hdir+"/menu.js",tplData("html_menu.js"));
  writeFileIf(hdir+"/navtree.css",tplData("html_navtree.css"));
  writeFileIf(hdir+"/navtree.js",tplData("html_navtree.js"));
  writeFileIf(hdir+"/search/search.css",tplData("html_search/search.css"));
  writeFileIf(hdir+"/search/search.js",tplData("html_search/search.js"));
  makeDirs(hdir+"/search");

  // ------------------------------------------------ nav tree
  NavNode *root=new NavNode();
  root->name=cfg.str("PROJECT_NAME"); root->url="index.html";
  std::string title=cfg.str("PROJECT_NAME")+" Documentation";
  std::map<std::string,std::vector<int> > navIndex;
  // collect documented classes
  std::vector<ClassDef*> dcs;
  for(size_t i=0;i<M.classes.size();i++){
    ClassDef *cd=M.classes[i];
    if(cd->isForward) continue;
    if(cd->documented) dcs.push_back(cd);
    else if(cfg.boolVal("EXTRACT_ALL")) dcs.push_back(cd);
  }
  NavNode *clsNode=NULL;
  if(!dcs.empty()){
    clsNode=new NavNode(); clsNode->name="Classes"; clsNode->url="annotated.html"; clsNode->parent=root;
    root->children.push_back(clsNode);
    NavNode *cl=new NavNode(); cl->name="Class List"; cl->url="annotated.html"; cl->childrenVar="annotated_dup"; cl->parent=clsNode;
    clsNode->children.push_back(cl);
    for(size_t i=0;i<dcs.size();i++){
      ClassDef *cd=dcs[i];
      NavNode *cn=new NavNode(); cn->name=cd->name; cn->url=classFileName(cd);
      cn->childrenVar=classFileName(cd).substr(0,classFileName(cd).size()-5);
      cn->parent=cl; cl->children.push_back(cn);
      for(size_t k=0;k<cd->members.size();k++){
        MemberDef *m=cd->members[k];
        if(!m->documented) continue;
        NavNode *mn=new NavNode(); mn->name=m->name; mn->url=classFileName(cd)+"#"+m->anchor; mn->parent=cn;
        cn->children.push_back(mn);
      }
    }
    NavNode *ci=new NavNode(); ci->name="Class Index"; ci->url="classes.html"; ci->parent=clsNode;
    clsNode->children.push_back(ci);
    NavNode *cm=new NavNode(); cm->name="Class Members"; cm->url="functions.html"; cm->parent=clsNode;
    clsNode->children.push_back(cm);
    NavNode *all=new NavNode(); all->name="All"; all->url="functions.html"; all->parent=cm;
    cm->children.push_back(all);
    NavNode *fn=new NavNode(); fn->name="Functions"; fn->url="functions_func.html"; fn->parent=cm;
    cm->children.push_back(fn);
  }
  collectIndex(root,std::vector<int>(),navIndex);
  // ---- write navtreedata.js
  {
    std::string o=licenceBlock();
    o+="var NAVTREE =\n[\n"+navTreeJson(root,1,false)+"\n];\n\n";
    o+="var NAVTREEINDEX =\n[\n\"annotated.html\"\n];\n\n";
    o+="const SYNCONMSG = 'click to disable panel synchronization';\nconst SYNCOFFMSG = 'click to enable panel synchronization';\nconst LISTOFALLMEMBERS = 'List of all members';";
    writeFileIf(hdir+"/navtreedata.js",o);
  }
  // ---- write navtreeindex0.js
  {
    std::string o="var NAVTREEINDEX0 =\n{\n";
    bool first=true;
    for(std::map<std::string,std::vector<int> >::iterator it=navIndex.begin();it!=navIndex.end();++it){
      if(!first) o+=",\n";
      first=false;
      o+="\""+it->first+"\":[";
      for(size_t i=0;i<it->second.size();i++){ if(i) o+=","; o+=numToString(it->second[i]); }
      o+="]";
    }
    o+=",\n\"pages.html\":[]\n};\n";
    writeFileIf(hdir+"/navtreeindex0.js",o);
  }
  // ---- write menudata.js
  {
    std::string o=licenceBlock();
    o+="var menudata={children:[\n";
    o+="{"+"text:\"Main Page\",url:\"index.html\"}";
    if(clsNode){
      o+=",\n"+menuJson(clsNode,0);
    }
    o+="]}";
    writeFileIf(hdir+"/menudata.js",o);
  }
  // ---- annotated.html
  {
    std::string c;
    c+="<div class=\"textblock\">Here are the classes, structs, unions and interfaces with brief descriptions:</div><div class=\"directory\">\n";
    c+="<table class=\"directory\">\n";
    int row=0;
    for(size_t i=0;i<dcs.size();i++){
      ClassDef *cd=dcs[i];
