static std::string memberUrl(MemberDef *m, const std::string &fileBase){
  return fileBase+".html#"+m->anchor;
}

void buildModel(const Config &cfg,const std::vector<std::string> &files){
  for(size_t i=0;i<files.size();i++){
    FileParser *fp=new FileParser(files[i],baseNameOf(files[i]));
    fp->run();
    FileEntry *fe=new FileEntry();
    fe->path=files[i]; fe->name=baseNameOf(files[i]);
    fe->docName=fileDocName(files[i]);
    fe->documented=fp->fileDocumented;
    fe->brief=fp->fileBrief; fe->detailed=fp->fileDetailed;
    fe->classes=fp->classes; fe->enums=fp->enums; fe->members=fp->members;
    fe->namespaces=fp->namespaces;
    M.files.push_back(fe);
    for(size_t k=0;k<fp->classes.size();k++){
      ClassDef *cd=fp->classes[k];
      cd->anchor="";
      M.classes.push_back(cd);
    }
    for(size_t k=0;k<fp->enums.size();k++) M.enums.push_back(fp->enums[k]);
    for(size_t k=0;k<fp->members.size();k++) M.members.push_back(fp->members[k]);
    for(size_t k=0;k<fp->namespaces.size();k++) M.namespaces.push_back(fp->namespaces[k]);
  }
  // anchors
  for(size_t i=0;i<M.classes.size();i++){
    ClassDef *cd=M.classes[i];
    DocParts p=splitDoc(cd->brief,false);
    cd->documented=!p.brief.empty();
    for(size_t k=0;k<cd->members.size();k++){
      MemberDef *m=cd->members[k];
      DocParts p2=splitDoc(m->brief,false);
      m->documented=!p2.brief.empty();
      m->anchor=md5hex(m->qualName+m->args);
    }
  }
  for(size_t i=0;i<M.enums.size();i++){
    EnumDef *ed=M.enums[i];
    DocParts p=splitDoc(ed->brief,false);
    ed->documented=!p.brief.empty();
    for(size_t k=0;k<ed->values.size();k++){
      MemberDef *m=ed->values[k];
      DocParts p2=splitDoc(m->brief,false);
      m->documented=!p2.brief.empty();
      m->anchor=md5hex(m->qualName);
    }
  }
  for(size_t i=0;i<M.members.size();i++){
    MemberDef *m=M.members[i];
    if(m->kind=="enumValue") continue;
    DocParts p=splitDoc(m->brief,false);
