static std::string condBlocks(const std::string &t, const std::map<std::string,bool> &cond){
  std::string out; size_t i=0;
  while(i<t.size()){
    size_t b=t.find("<!--BEGIN ",i);
    if(b==std::string::npos){ out+=t.substr(i); break; }
    size_t e=t.find("-->",b);
    if(e==std::string::npos){ out+=t.substr(i); break; }
    std::string key=t.substr(b+10,e-(b+10));
    size_t endKey=t.find("<!--END "+key+"-->",e);
    if(endKey==std::string::npos){ out+=t.substr(i,b-i); break; }
    size_t endEnd=endKey+8+key.size()+3;
    size_t lineStart=b; while(lineStart>0 && t[lineStart-1]!='\n') lineStart--;
    size_t lineEndOfEnd=endEnd; while(lineEndOfEnd<t.size() && t[lineEndOfEnd]!='\n') lineEndOfEnd++;
    std::string prefix=t.substr(lineStart,b-lineStart);
    std::string suffix=t.substr(endEnd,lineEndOfEnd-endEnd);
    bool sameLine=(t.find('\n',b)==std::string::npos || t.find('\n',b)>endEnd);
