new=r'''DocParts splitDoc(const std::string &raw,bool javaAutoBrief){
  DocParts p;
  std::vector<std::string> nl=normalizeDocLines(raw);
  std::string text;
  for(size_t z=0;z<nl.size();z++){ text+=nl[z]; if(z+1<nl.size()) text+="\n"; }
  std::vector<std::string> lines=splitStr(text,"\n");
  // detect an explicit brief command
  size_t briefStart=std::string::npos, briefEnd=0;
  bool hasCmd=false;
  for(size_t i=0;i<lines.size();i++){
    std::string line=lines[i];
    if(line.size()>1 && (line[0]=='@'||line[0]=='\\')){
      size_t sp=1;
      while(sp<line.size() && (isalnum((unsigned char)line[sp])||line[sp]=='_'||line[sp]==':')) sp++;
      std::string cmd=line.substr(1,sp-1);
      if(cmd=="brief"){ hasCmd=true; briefStart=i; break; }
      if(!javaAutoBrief) break;   // first command that is not brief ends the search
    }
  }
  if(hasCmd){
    // brief: from briefStart until a blank line or the next command
    size_t i=briefStart;
    std::string first=lines[i];
    size_t sp=1;
    while(sp<first.size() && (isalnum((unsigned char)first[sp])||first[sp]=='_'||first[sp]==':')) sp++;
    std::string bt=first.substr(sp);
    briefEnd=i+1;
    while(briefEnd<lines.size()){
      std::string l=lines[briefEnd];
      if(stripWS(l).empty()){ briefEnd++; break; }
      if(l.size()>1 && (l[0]=='@'||l[0]=='\\')) break;
      bt+="\n"+l;
      briefEnd++;
    }
    p.hasBriefCmd=true;
    p.brief=bt;
    std::string rest;
    for(size_t k=briefEnd;k<lines.size();k++){ rest+=lines[k]; if(k+1<lines.size()) rest+="\n"; }
    p.rest=rest;
  } else {
    // first paragraph is the brief
    size_t i=0;
    std::string bt;
    bool got=false;
    while(i<lines.size()){
      std::string l=lines[i];
      if(stripWS(l).empty()){ i++; break; }
      if(l.size()>1 && (l[0]=='@'||l[0]=='\\')){ break; }
      bt+=(bt.empty()?"":"\n")+l;
      got=true; i++;
    }
    p.brief=bt;
    std::string rest;
    for(size_t k=i;k<lines.size();k++){ rest+=lines[k]; if(k+1<lines.size()) rest+="\n"; }
    p.rest=rest;
  }
  return p;
}

