{"command": "cd /workspace && python3 - <<'PY'
p='src/htmlgen.cpp'
s=open(p).read()
anchor='''  // ---- annotated.html'''
add=r'''  // ---- class pages, classTest.js, members pages
  {
    for(size_t i=0;i<dcs.size();i++){
      ClassDef *cd=dcs[i];
      std::string fn=classFileName(cd);
      std::string base=fn.substr(0,fn.size()-5);
      // nav children var js
      std::string js="var "+base+" =\n[\n";
      {
        std::vector<MemberDef*> ms;
        for(size_t k=0;k<cd->members.size();k++){ if(cd->members[k]->documented) ms.push_back(cd->members[k]); }
        for(size_t k=0;k<ms.size();k++){
          js+="    [ \""+htmlEscape(ms[k]->name)+"\", \""+fn+"#"+ms[k]->anchor+"\", null ]";
          if(k+1<ms.size()) js+=",";
          js+="\n";
        }
      }
      js+="];";
      writeFileIf(hdir+"/"+base+".js",js);
      // class page
      std::string c=classPageContent(cd);
      std::vector<std::string> ne;
      ne.push_back("<li class=\"navelem\"><a href=\""+fn+"\">"+htmlEscape(cd->name)+"</a></li>");
      writePage(hdir+"/"+fn, "", htmlEscape(cd->name)+" Class Reference", c, ne, true, "");
      // members page
      std::string c2="\n<p>This is the complete list of members for <a class=\"el\" href=\""+fn+"\">"+htmlEscape(cd->name)+"</a>, including all inherited members.</p>\n";
      c2+="<table class=\"directory\">\n";
      {
        std::vector<MemberDef*> ms;
        for(size_t k=0;k<cd->members.size();k++){ if(cd->members[k]->documented) ms.push_back(cd->members[k]); }
        std::sort(ms.begin(),ms.end(),[](MemberDef*a,MemberDef*b){ return strCompareIC(a->name,b->name)<0; });
        for(size_t k=0;k<ms.size();k++){
          MemberDef *m=ms[k];
          c2+="  <tr class=\""+std::string((k%2)?"odd":"even")+"\"><td class=\"entry\"><a class=\"el\" href=\""+fn+"#"+m->anchor+"\">"+htmlEscape(m->name)+"</a>";
          if(m->kind=="function") c2+=htmlEscape(m->args)+(m->isConst?" const":"");
          c2+="</td><td class=\"entry\"><a class=\"el\" href=\""+fn+"\">"+htmlEscape(cd->name)+"</a></td><td class=\"entry\"></td></tr>\n";
        }
      }
      c2+="</table>";
      writePage(hdir+"/"+base+"-members.html", "", htmlEscape(cd->name)+" Member List", c2, std::vector<std::string>(), false, "");
    }
  }
  // ---- doxygen_crawl.html
  {
    std::string o="<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"https://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\n";
    o+="<html xmlns=\"http://www.w3.org/1999/xhtml\" lang=\"en-US\">\n<head>\n<title>Validator / crawler helper</title>\n";
    o+="<meta http-equiv=\"Content-Type\" content=\"text/xhtml;charset=UTF-8\"/>\n";
    o+="<meta http-equiv=\"X-UA-Compatible\" content=\"IE=11\"/>\n";
    o+="<meta name=\"generator\" content=\"Doxygen "+DOXY_VERSION+"\"/>\n";
    o+="<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n";
    o+="</head>\n<body>\n";
    std::set<std::string> urls;
    urls.insert("annotated.html");
    urls.insert("classes.html");
    urls.insert("functions.html");
    urls.insert("functions_func.html");
    urls.insert("index.html");
    urls.insert("doxygen_crawl.html");
    for(size_t i=0;i<dcs.size();i++){
      ClassDef *cd=dcs[i];
      urls.insert(classFileName(cd));
      urls.insert(classFileName(cd).substr(0,classFileName(cd).size()-5)+"-members.html");
      for(size_t k=0;k<cd->members.size();k++) if(cd->members[k]->documented) urls.insert(classFileName(cd)+"#"+cd->members[k]->anchor);
    }
    std::vector<std::string> uv(urls.begin(),urls.end());
    std::sort(uv.begin(),uv.end());
    for(size_t i=0;i<uv.size();i++) o+="<a href=\""+uv[i]+"\"/>\n";
    o+="</body>\n</html>\n";
    writeFileIf(hdir+"/doxygen_crawl.html",o);
  }
  // ---- index.html
  {
    std::string c="<a href=\"doxygen_crawl.html\"></a>\n";
    writePage(hdir+"/index.html","", "Main Page", c, std::vector<std::string>(), false, "");
  }
  // ---- search data
  {
    struct Sec { std::string name; std::string label; std::vector<std::string> letters; std::map<std::string,std::vector<std::string> > entries; };
    std::vector<Sec> secs;
    Sec all; all.name="all"; all.label="All";
    Sec cls; cls.name="classes"; cls.label="Classes";
    Sec fnc; fnc.name="functions"; fnc.label="Functions";
    // collect entries
    for(size_t i=0;i<dcs.size();i++){
      ClassDef *cd=dcs[i];
      std::string fn=classFileName(cd);
      std::string key=lowerStr(cd->name)+"_0";
      std::string ent="['"+htmlEscape(cd->name)+"',['../"+fn+"',1,'"+(cls.name=="classes"?"":"")+"']]";
      cls.entries[lowerStr(cd->name)].push_back(ent);
      cls.letters.push_back(lowerStr(cd->name).substr(0,1));
    }
    for(size_t i=0;i<dcs.size();i++){
      ClassDef *cd=dcs[i];
      for(size_t k=0;k<cd->members.size();k++){
        MemberDef *m=cd->members[k];
        if(!m->documented) continue;
        if(m->kind!="function") continue;
        std::string fn=classFileName(cd);
        std::string url="../"+fn+"#"+m->anchor;
        std::string scope=cd->name;
        fnc.entries[lowerStr(m->name)].push_back("['"+htmlEscape(m->name)+"','"+url+"',1,'"+htmlEscape(scope)+"']");
        fnc.letters.push_back(lowerStr(m->name).substr(0,1));
      }
    }
    // all section: group by name, with class+member entries
    {
      std::map<std::string,std::vector<std::string> > groups;
      for(size_t i=0;i<dcs.size();i++){
        ClassDef *cd=dcs[i];
        groups[lowerStr(cd->name)].push_back("['"+htmlEscape(cd->name)+"',['../"+classFileName(cd)+"',1,'"+htmlEscape(cd->name)+"']]");
      }
      for(size_t i=0;i<dcs.size();i++){
        ClassDef *cd=dcs[i];
        for(size_t k=0;k<cd->members.size();k++){
          MemberDef *m=cd->members[k];
          if(!m->documented) continue;
          if(m->kind!="function") continue;
          std::string scope=cd->name;
          if(groups[lowerStr(m->name)].size()>1) scope=m->qualName+"("+m->args+")";
          groups[lowerStr(m->name)].push_back("['"+htmlEscape(m->name)+"',['../"+classFileName(cd)+"#"+m->anchor+"',1,'"+htmlEscape(scope)+"']]");
        }
      }
      for(std::map<std::string,std::vector<std::string> >::iterator it=groups.begin();it!=groups.end();++it){
        all.entries[it->first].push_back(it->second[0]);
        for(size_t k=1;k<it->second.size();k++) all.entries[it->first][0]=all.entries[it->first][0].substr(0,all.entries[it->first][0].size()-1)+","+it->second[k]+"]";
        all.letters.push_back(it->first.substr(0,1));
      }
    }
    secs.push_back(all); secs.push_back(cls); secs.push_back(fnc);
    // letters sorted+unique
    for(size_t i=0;i<secs.size();i++){
      std::sort(secs[i].letters.begin(),secs[i].letters.end());
      secs[i].letters.erase(std::unique(secs[i].letters.begin(),secs[i].letters.end()),secs[i].letters.end());
    }
    // files
    for(size_t si=0;si<secs.size();si++){
      Sec &sc=secs[si];
      for(size_t li=0;li<sc.letters.size();li++){
        std::string letter=sc.letters[li];
        std::vector<std::string> keys;
        for(std::map<std::string,std::vector<std::string> >::iterator it=sc.entries.begin();it!=sc.entries.end();++it){
          if(it->first.substr(0,1)!=letter) continue;
          keys.push_back(it->first);
        }
        if(keys.empty()) continue;
        std::string o="var searchData=\n[\n";
        for(size_t k=0;k<keys.size();k++){
          std::vector<std::string> &ents=sc.entries[keys[k]];
          std::string ent="['"+keys[k]+"_0',["+ents[0];
          for(size_t q=1;q<ents.size();q++) ent+=","+ents[q];
          ent+="]]";
          o+="  "+ent;
          if(k+1<keys.size()) o+=",";
          o+="\n";
        }
        o+="];\n";
        writeFileIf(hdir+"/search/"+sc.name+"_"+numToString((int)li)+".js",o);
      }
    }
    std::string sd="var indexSectionsWithContent =\n{\n";
    for(size_t si=0;si<secs.size();si++){
      if(si) sd+=",\n";
      sd+="  "+numToString((int)si)+": \""+joinStr(secs[si].letters,"")+"\"";
    }
    sd+="\n};\n\nvar indexSectionNames =\n{\n";
    for(size_t si=0;si<secs.size();si++){ if(si) sd+=",\n"; sd+="  "+numToString((int)si)+": \""+secs[si].name+"\""; }
    sd+="\n};\n\nvar indexSectionLabels =\n{\n";
    for(size_t si=0;si<secs.size();si++){ if(si) sd+=",\n"; sd+="  "+numToString((int)si)+": \""+secs[si].label+"\""; }
    sd+="\n};\n\n";
    writeFileIf(hdir+"/search/searchdata.js",sd);
  }
  // ---- annotated.html'''
s=s.replace(anchor,add,1)
open(p,'w').write(s)
PY
./compile.sh 2>&1|head -10"}

